window.JVVNL_BANKS=window.JVVNL_BANKS||{};JVVNL_BANKS['financial-accounting']={"slug":"financial-accounting","name":"Advanced Financial Accounting","count":135,"questions":[{"id":"pyq-395","sourceNumber":395,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is INCORRECT in the context of accounting concepts?","options":["In case of precious metals like gold, the revenue is recognised when the gold is mined and not necessarily when it is sold.","In case of sale on instalment basis under hire purchase transactions, cash received in the form of instalment is the amount of revenue recognised.","Accounting systems based on the accural concept is also known as the Mercantile System of Accounting.","The realization concept is related to both revenues and expenses."],"answer":3,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why D is correct — incorrect statement:** The realisation concept is primarily concerned with when revenue is recognised. Expenses are addressed more directly by the matching/accrual concepts, although revenue recognition and expense recognition interact in preparing financial statements. The other statements reflect the source’s traditional accounting treatment. **Exam distinction:** realisation → revenue; matching → expenses with related revenue.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b71e5e71b4fbd1d53128ed6f88c3606f6f476f7263419042772d07a1ba21783a","kind":"pyq"},{"id":"pyq-396","sourceNumber":396,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following errors will reflect in the trial balance?","options":["A sum of ₹ 500 paid to Mr A's account posted twice in his account.","Not recording a credit purchase of furniture.","Treating a sale of fixed assets as a normal sale.","An amount received from Mr A credited to Mr B's account wrongly."],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct:** If a payment of ₹500 to Mr A is posted twice to Mr A’s account while the corresponding cash credit is recorded only once, the ledger debits and credits no longer agree, so the trial balance can reveal the difference. Omitting a transaction entirely or posting an amount to the wrong personal account may leave the trial balance balanced. **Exam cue:** one-sided or unequal posting often affects trial-balance agreement.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"59ea0bb82f2e9ee23dc3a4d207ce591f859a1557081b9b192bd7bdfd866c74c5","kind":"pyq"},{"id":"pyq-397","sourceNumber":397,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following accounts will typically have a debit balance in the trial balance?","options":["Accumulated depreciation","Purchase of stationery","Purchases return","Outstanding salaries"],"answer":1,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why B is correct — Purchase of stationery:** Purchases/expense accounts normally have debit balances. Accumulated depreciation is a contra-asset with a credit balance; purchases return normally has a credit balance; outstanding salaries is a liability and normally has a credit balance. **Memory cue:** expenses/purchases → debit; liabilities, income and returns outward → credit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"f061fbcedd23a011a55061045406a50ac6a351ecc4e2915fe1a42a52a756007d","kind":"pyq"},{"id":"pyq-398","sourceNumber":398,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In case a Provision for Depreciation Account is NOT maintained, the correct journal entry for recording the amount of depreciation is:","options":["Profit and Loss Account Dr To Asset Account","Asset Account Dr To Depreciation Account","Depreciation Account Dr To Profit and Loss Account","Depreciation Account Dr To Asset Account"],"answer":3,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why D is correct:** If no Provision for Depreciation/Accumulated Depreciation Account is maintained, depreciation is credited directly to the asset account. The entry is **Depreciation Account Dr. To Asset Account**; the depreciation expense is then transferred to the Profit and Loss Account as part of the closing process. **Exam cue:** direct method reduces the asset’s book value.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"89cf3d4bc7fd85645e6a1e56720ddf1e94e5310b7e8095486dd50a0e5b18d948","kind":"pyq"},{"id":"pyq-399","sourceNumber":399,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is true?","options":["Convention of full disclosure is also known as convention of prudence.","Accounting conventions are established by law.","There is no personal bias in the adoption of accounting conventions .","There is no uniformity in the application of accounting conventions in different enterprises."],"answer":3,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why D is correct:** Accounting conventions developed through practice and professional acceptance rather than all being directly established by a single law. Their application may vary among enterprises depending on the applicable standards, circumstances and policies, so the statement about lack of uniformity is the true one in this set. **Exam cue:** conventions guide practice, while standards/regulations can impose uniform requirements.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following statements is true?","options":["Convention of full disclosure is also known as convention of prudence.","Accounting conventions are established by law.","There is no personal bias in the adoption of accounting conventions .","There is no uniformity in the application of accounting conventions in different enterprises."],"answer":3,"explanation":"**Why D is correct:** Accounting conventions developed through practice and professional acceptance rather than all being directly established by a single law. Their application may vary among enterprises depending on the applicable standards, circumstances and policies, so the statement about lack of uniformity is the true one in this set. **Exam cue:** conventions guide practice, while standards/regulations can impose uniform requirements.","revision":"original","contentSignature":"f7d9635e7e821d4a500ff1e4e2901fff7efb9334390109f327fcbb327fccfdbd"}],"contentSignature":"f7d9635e7e821d4a500ff1e4e2901fff7efb9334390109f327fcbb327fccfdbd","legacySubject":"financial-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-400","sourceNumber":400,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"When an income is received in advance, the treatment in the Profit & Loss account and balance sheet, respectively, will be:","options":["deducted from the respective income on the credit side; shown on the liabilities side","deducted from the respective income on the credit side; shown on the assets side","added to the respective income on the credit side; shown on the assets side","added to the respective income on the credit side; shown on the liabilities side"],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct:** Income received in advance is unearned income at the reporting date. It is deducted from the relevant income on the credit side of the Profit and Loss Account to recognise only the earned portion, and the unearned amount is shown as a liability because the service/goods obligation remains. **Exam cue:** advance receipt = cash received, revenue not yet earned → liability.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"c0d5cfd00dd4c4142784a2dc962c8f45f5bb2fbd984ef6ed51839f3516fe2f4b","kind":"pyq"},{"id":"pyq-401","sourceNumber":401,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Receipts and payments account includes which of the following? (i) All receipts and payments related to the current year. (ii) All receipts and payments related to the previous or future year(s). (iii) All receipts and payments irrespective of the natural (both revenue and capital).","options":["Only (ii)","Only (i) and {ii)","Only (i)","(i), (ii) and (iii)"],"answer":3,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why D is correct — all three:** A Receipts and Payments Account records all cash/bank receipts and payments during the period, regardless of whether they relate to the current, previous or future accounting period. It includes both revenue and capital items and is prepared on a cash basis. **Exam distinction:** Receipts and Payments = cash basis/all periods; Income and Expenditure = accrual basis/current period.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"9ffe9e564021743aa0f4ea7c872405b809aec98cb9ce2a4e8fc25c1f0ddd5731","kind":"pyq"},{"id":"pyq-402","sourceNumber":402,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is correct?","options":["Bank will draw a bill on a customer at the time of overdraft.","Oral bill of exchange is also valid.","In case of endorsement of bill, endorser debits endorsee and credits bills receivable account.","If the bill is assigned by the drawer, it is invalid."],"answer":2,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why C is correct:** When a bill is endorsed to another party, the endorser transfers the bill receivable. In the endorser’s books, the endorsee account is debited and Bills Receivable is credited, reflecting the transfer of the instrument. An oral bill is not a valid bill of exchange because the instrument must meet legal requirements, including being in writing. **Exam cue:** endorsement transfers the right to receive payment.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following statements is correct?","options":["Bank will draw a bill on a customer at the time of overdraft.","Oral bill of exchange is also valid.","In case of endorsement of bill, endorser debits endorsee and credits bills receivable account.","If the bill is assigned by the drawer, it is invalid."],"answer":2,"explanation":"**Why C is correct:** When a bill is endorsed to another party, the endorser transfers the bill receivable. In the endorser’s books, the endorsee account is debited and Bills Receivable is credited, reflecting the transfer of the instrument. An oral bill is not a valid bill of exchange because the instrument must meet legal requirements, including being in writing. **Exam cue:** endorsement transfers the right to receive payment.","revision":"original","contentSignature":"42db3ffa605adfd72cdffee429075cb8476d9d93f863dfb6dc989ab3e36015ae"}],"contentSignature":"42db3ffa605adfd72cdffee429075cb8476d9d93f863dfb6dc989ab3e36015ae","legacySubject":"financial-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-404","sourceNumber":404,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A machine is purchased for ₹8,000 and is wrongly recorded in the purchases account. Due to this error, the trial balance will:","options":["show a difference of ₹4,000","not show any difference","show a difference of ₹16,000","show a difference of ₹8,000"],"answer":1,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why B is correct — no difference in the trial balance:** Purchasing machinery is a capital transaction, but if the amount is wrongly debited to Purchases instead of Machinery, the debit side is still recorded for the same amount. Total debits and credits remain equal, so the trial balance will not reveal this error of principle. **Exam cue:** wrong account, correct side and amount → trial balance may still agree.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"d680370e3427e0ef70dfee9b0a60b55f7e86d76da4633ec4fe02a9b8b04cfc70","kind":"pyq"},{"id":"pyq-405","sourceNumber":405,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A state of deterioration, damage done to a building or other property during tenancy can be referred to as:","options":["dilapidation","depletion","depreciation","obsolescence"],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct — Dilapidation:** Dilapidation refers to damage or deterioration of a building/property, often in the context of a tenant’s occupation and obligations at the end of a tenancy. Depletion applies to natural resources, depreciation to allocating the cost of tangible assets over useful lives, and obsolescence to loss of usefulness due to new technology or changing needs.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"4334d340c1213ef69c734de824aa354704337cbfdd9bd3ebec0a3ea5bac60db9","kind":"pyq"},{"id":"pyq-406","sourceNumber":406,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is true in the context of capital and revenue expenditure?","options":["Legal fees to acquire property is capital expenditure .","Overhaul expenses of a second-hand machine purchased are revenue expenditure","Amount spent for the replacement of a worn-out pa1i of a machine is capital expenditure","Expenses in connection with obtaining a license for running a cinema are revenue expenditure."],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct:** Legal fees directly attributable to acquiring property are part of the cost of acquiring that asset and are capital expenditure. Routine repairs are usually revenue expenditure; replacement/overhauling costs require assessment of whether they merely maintain the asset or create additional future benefits. A licence fee to operate a cinema may be recurring revenue expenditure depending on the term and nature of the licence, so the direct acquisition-related legal fee is the clearest correct statement here. **Exam cue:** directly attributable acquisition cost → capitalise.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"fe9ca75d596da895348c3714900b7468c958350ec9685c08e58aa08651e7fa90","kind":"pyq"},{"id":"pyq-407","sourceNumber":407,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is INCORRECT in the comext of Not-for-profit organisations?","options":["The main sources of income of such organisations are: (i) subscriptions from members. (ill donations. (iii) gram-in-aid,etc .","The income and expenditure account lists both the revenue and capital receipts and payments (for past. current and future periods).","Final accounts for not-for-profit organisations comprise receipts and payment account: income and expenditure account; and balance sheet at the end of the year.","Not-for-profit organisations are organised as trusts/societies and have members, not owners."],"answer":1,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why B is incorrect:** The Income and Expenditure Account of a not-for-profit organisation records revenue income and revenue expenditure on an accrual basis for the current period. It does not list all capital receipts/payments and all past/future-period cash transactions; those are characteristics of the Receipts and Payments Account. The final accounts generally include Receipts and Payments, Income and Expenditure, and a Balance Sheet. **Exam distinction:** capital + all periods → Receipts and Payments; current-period revenue → Income and Expenditure.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"d1ca9a6ef1416d9ef5de09957a9ead493ccbd24221b195878409d1258adbcb3e","kind":"pyq"},{"id":"pyq-408","sourceNumber":408,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The bank passbook of Mr. P showed a credit balance of ₹924 as on 31 March 2021 . When checked with cashbook the fllowing points were noted. 1. Payment of a utility bill of ₹200 as per Mr. p's standing instructions was made, which was not retlec1ing in the cash book. 2. A cheque of ₹65 deposited in the bank on 28 March 2021 was not cleared till 4 April 1021. 3. Cheque drawn by and posted to a parry for ₹46 by Mr. P on 31 March 2021 was presented to the bank on 12 April, 2021. What will be the bank balance as per cash book as on 31 March 2021?","options":["Debit balance of ₹1,143","Debit balance of ₹1,235","Credit balance of ₹705","Credit balance of ₹1,189"],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct — debit balance ₹1,143 in the Cash Book:** Start with the passbook credit/favourable balance ₹924. Add the utility payment ₹200 because the bank has paid it but the cash book has not recorded it. Add the uncleared deposited cheque ₹65 because the cash book already records it but the bank has not credited it yet. Subtract the unpresented cheque ₹46 because it is recorded in the cash book but not yet in the passbook. Cash-book balance = ₹924 + ₹200 + ₹65 − ₹46 = **₹1,143 favourable/debit**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"e505444fcc7e83d21fcb9f2b9fc4500f7f62b66dd6e9ee570aeb0cd57c5c5536","kind":"pyq"},{"id":"pyq-410","sourceNumber":410,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is correct in the context of single-entry system?","options":["Credit sales during the year can be ascertained as the balancing figure in the total creditor account.","The objective of preparing a statement of affairs is to estimate the balance in the capital account on a particular date.","Credit purchase during the year can be ascertained by preparing the total debtors account.","Statement of affairs is reliable as it is prepared from double entry record."],"answer":1,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why B is correct:** Under a single-entry system, a Statement of Affairs is prepared to estimate assets and liabilities and derive the proprietor’s capital at a particular date. It is not fully reliable like a balance sheet prepared from complete double-entry records, because the underlying records may be incomplete. The other options reverse the debtor/creditor accounts or overstate the reliability of the statement. **Exam cue:** Statement of Affairs → estimated capital.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following statements is correct in the context of single-entry system?","options":["Credit sales during the year can be ascertained as the balancing figure in the total creditor account.","The objective of preparing a statement of affairs is to estimate the balance in the capital account on a particular date.","Credit purchase during the year can be ascertained by preparing the total debtors account.","Statement of affairs is reliable as it is prepared from double entry record."],"answer":1,"explanation":"**Why B is correct:** Under a single-entry system, a Statement of Affairs is prepared to estimate assets and liabilities and derive the proprietor’s capital at a particular date. It is not fully reliable like a balance sheet prepared from complete double-entry records, because the underlying records may be incomplete. The other options reverse the debtor/creditor accounts or overstate the reliability of the statement. **Exam cue:** Statement of Affairs → estimated capital.","revision":"original","contentSignature":"7dbdd2ed6ecf39bd07f0c8276f00f90dc7260f92541ea2c72839f8ac9c92d075"}],"contentSignature":"7dbdd2ed6ecf39bd07f0c8276f00f90dc7260f92541ea2c72839f8ac9c92d075","legacySubject":"financial-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-411","sourceNumber":411,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A credit balance in the bank passbook indicates a/an ____ balance, and debit balance in the cash book indicates a/an ___ balance.","options":["favourable; overdraft","overdraft; favourable","favourable; favourable","overdraft; overdraft"],"answer":2,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why C is correct — favourable; favourable:** A credit balance in the bank passbook generally means the bank owes the customer that amount, so it is a favourable balance. A debit balance in the cash book’s bank column also normally indicates money available in the bank. **Exam trap:** the bank’s books and customer’s books use opposite debit/credit perspectives.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"a4b0364fa1432a30907c9aae16eedfd4dcc715ef08f24d30cd5ea8685ff8582a","kind":"pyq"},{"id":"pyq-412","sourceNumber":412,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is correct in the context of a trading account?","options":["Trading account is debited with the net purchases and credited with the net sales.","Net purchases is the sum of cash, credit purchase and the amount of return outwards.","Goods received on consignment basis are treated as purchases.","Goods received on sale or return basis are treated as purchases."],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct:** A trading account is debited with net purchases and credited with net sales to calculate gross profit/loss, alongside opening and closing inventory and direct expenses. Net purchases = cash purchases + credit purchases − returns outward. Goods held on consignment are not the consignee’s purchases, and goods on sale-or-return are not treated as sales/purchases until acceptance under the relevant terms. **Exam cue:** ownership matters, not merely physical possession.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"80cfb14b77535ffad8f31ace620dd531d1205317c6fbb9581d0f58172bbbc494","kind":"pyq"},{"id":"pyq-413","sourceNumber":413,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is INCORRECT for self-balancing ledgers?","options":["Self-balancing ledger system implies a system of ledger keeping which classifies ledgers as per nature of transactions.","In self-balancing system, general ledger adjustment account is prepared in each of the subsidiary ledgers.","In self-balancing system, generally, three ledgers are prepared namely, debtor ledger, credit ledger and main ledger","Under sectional balancing system, if the error affects the total of debtors and creditors accounts, it is rectified by adjusting the accounts of debtors and creditors itself without any additional entries."],"answer":3,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why D is the correct answer:** In a self-balancing ledger system, separate adjustment accounts are maintained to reconcile the general ledger with sales/debtors and purchases/creditors ledgers. Under sectional balancing, errors affecting total debtors or creditors may require control-account and corresponding ledger adjustments; they cannot always be corrected solely by altering individual personal accounts without the appropriate entries. **Exam cue:** self-balancing uses ledger adjustment accounts; sectional balancing uses control accounts within the relevant ledgers.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following statements is INCORRECT for self-balancing ledgers?","options":["Self-balancing ledger system implies a system of ledger keeping which classifies ledgers as per nature of transactions.","In self-balancing system, general ledger adjustment account is prepared in each of the subsidiary ledgers.","In self-balancing system, generally, three ledgers are prepared namely, debtor ledger, credit ledger and main ledger","Under sectional balancing system, if the error affects the total of debtors and creditors accounts, it is rectified by adjusting the accounts of debtors and creditors itself without any additional entries."],"answer":3,"explanation":"**Why D is the supplied answer:** In a self-balancing ledger system, separate adjustment accounts are maintained to reconcile the general ledger with sales/debtors and purchases/creditors ledgers. Under sectional balancing, errors affecting total debtors or creditors may require control-account and corresponding ledger adjustments; they cannot always be corrected solely by altering individual personal accounts without the appropriate entries. **Exam cue:** self-balancing uses ledger adjustment accounts; sectional balancing uses control accounts within the relevant ledgers.","revision":"original","contentSignature":"a99b02fc448675de7ea6cb6146abaf2e55ec878c922ba2f24f07818e2751c349"}],"contentSignature":"e6ed85ab41264141e78c4c00e2d0e8f3d778125e31e063c15dff491f7313cb97","legacySubject":"financial-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-414","sourceNumber":414,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"which of the following statements is INCORRECT in the context of a journal?","options":["Journal properly records transactions like expense accruals, rectification entries, adjusting entries, opening entries and closing entries.","Journal has three functions - analytical, recording and historical.","Journal is divided into two types - General Journal and Special Journal.","Journal is often referred to as the Principal Book of Ent1y."],"answer":3,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why D is correct — incorrect statement:** A journal is traditionally called the book of original entry because transactions are first recorded there (or in subsidiary books). The ledger is generally described as the principal book of accounts. Journals can record adjustments, accruals, opening/closing and rectification entries and serve analytical, recording and historical functions. **Exam cue:** journal = original entry; ledger = principal book.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"aa3c696c09119a832675b11b0a29ecdcf790108cc79fee11242d0d3b381c6980","kind":"pyq"},{"id":"pyq-415","sourceNumber":415,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In balance sheet, when finance are at top level and current liabilities at the bottom level. What is said this thing.","options":["sorted in order of permanence","sorted in order of priority","sorted in order of liquidity","sorted in order of importance"],"answer":0,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why A is correct — order of permanence:** A balance sheet arranged by order of permanence lists items expected to remain in the business for longer periods near the top and more short-term/current items lower down. A liquidity order instead arranges assets by how quickly they can be converted to cash. **Exam distinction:** permanence = long-term first; liquidity = most liquid first.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"2a681a7c2cd9c273b9bdda7a6a6ec2b78def8dcd672aec640f0196ed5ce43ec1","kind":"pyq"},{"id":"pyq-416","sourceNumber":416,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following is/are control account(s) maintained in the self-balancing ledger system? (i) Bought ledger adjustment account (ii) Sales ledger adjustment account (iii) General ledger adjustment account","options":["Only (i)","Both (i) and (ii)","Only (iii)","Only (ii)"],"answer":1,"source":"SSC CGL Tier-2 AAO, Jan 2022","explanation":"**Why B is correct — both (i) and (ii):** In a self-balancing ledger system, a Bought Ledger Adjustment Account reconciles the total creditors’ ledger and a Sales Ledger Adjustment Account reconciles the total debtors’ ledger. These control/adjustment accounts help keep separate ledgers self-balancing. **Exam cue:** bought ledger → creditors; sales ledger → debtors.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"82b896969b3242d759f10ed17a0005e2fba4b8979b3324408cd61b6a78bf7868","kind":"pyq"},{"id":"pyq-417","sourceNumber":417,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following is an INCORRECT pair, in the context of the Adjustment Account given in General Ledger under self-balancing ledger system?","options":["Provision for bad debts - appear on credit side of debtors ledgers adjustment account","Bad debts - appear on credit side of debtors ledgers adjustment account","Bills payable dishonored - appear on credit side of creditors ledgers adjustment account","Interest debited to a customer - appear on debit side of debtors ledgers adjustment account"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why A is the supplied answer:** The provision for bad debts is an adjustment against receivables and is treated differently from a direct bad-debt write-off in the ledger-adjustment system. The option states that provision for bad debts appears on the credit side of the debtors’ ledger adjustment account; the source marks this as the incorrect pairing. The other pairings are intended to reflect the direction of adjustment for bad debts, dishonoured bills payable and interest charged to customers. **Source note:** adjustment-account sides are sensitive to the exact system and entry convention; check the original worked example if needed.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"272f5f493aec8bd70aae9a67c6842d4ac5269a31191dc5f242f480c4cc6be05e","kind":"pyq"},{"id":"pyq-419","sourceNumber":419,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following options DO NOT relate to examples of revenue expenditure? a) Repair expenses b) Insurance expense c) Installation expenses d) overhauling expenses of second-hand machinery","options":["Only c and d","All of a, b, c and d","Only a and b","Only a, band c"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why A is correct — only c and d:** Routine repair expenses and insurance are usually revenue expenditures because they maintain or protect assets during ordinary operations. Installation expenses directly attributable to bringing machinery into working condition are capitalised, and overhauling a second-hand machine may be capital if needed to bring it to working condition or increase future benefits. **Exam cue:** installation/initial overhaul to ready an asset → capital; routine maintenance → revenue.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"6d7a628a7b171dc6a55a70b770399923bb5cec9797c2999ee98f84d03e485ad0","kind":"pyq"},{"id":"pyq-420","sourceNumber":420,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following pairs is NOT correctly matched in the context of account balances shown in the Trial Balance?","options":["Sales account - Credit side","Discount received account - Credit side","Plant and machinery account - Debit side","Bills receivable account - Credit side"],"answer":3,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why D is correct — Bills receivable:** Sales and discount received accounts normally have credit balances. Plant and machinery and bills receivable are assets and normally have debit balances. Therefore “Bills receivable account — Credit side” is the incorrectly matched pair. **Memory cue:** asset balances → debit; income and liabilities → credit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"0bb081241d07240106088a9b7255112d928978b57689acfc41a673b3a16daec4","kind":"pyq"},{"id":"pyq-421","sourceNumber":421,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Failure to differentiate between capital and revenue expenditure results in Errors of ___ .","options":["Omission","Commission","Principle","Compensation"],"answer":2,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why C is correct — Error of principle:** Capital expenditure and revenue expenditure are different in nature. Recording a capital item as revenue, or vice versa, violates the accounting principles for classification and is an error of principle. It may not cause the trial balance to disagree because the debit and credit amounts can still be equal. **Exam cue:** wrong accounting treatment/classification → error of principle.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"2734a3ce2a0abe43ab08242cb8c20bbd4dfe40c97759da904ca139a2275d3e16","kind":"pyq"},{"id":"pyq-422","sourceNumber":422,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A trial balance shows (i) Credit balances (ii) Debit balances","options":["Both (i) and (ii)","Only (i)","Only (ii)","Either (i) or (ii)"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why A is correct — both debit and credit balances:** A trial balance lists ledger account balances, which may be debit or credit depending on the account type. Assets and expenses normally have debit balances; liabilities, capital and income normally have credit balances, with exceptions for contra accounts and unusual balances. **Exam cue:** a trial balance contains both sides.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"4ac1d4305907d550e86abff1694d8c42ebde1fe75097536a06eaa8834fbb3102","kind":"pyq"},{"id":"pyq-423","sourceNumber":423,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following is/are INCORRECT match(es) of the account maintained in the context of self-balancing ledgers? (i) Bought ledger adjustment account - Total creditors account (ii) Sales ledger adjustment account - Total debtors account","options":["Only (i)","Neither (i) or (ii)","Only (ii)","Both (i) and (ii)"],"answer":1,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why B is correct — neither is incorrect:** Bought Ledger Adjustment Account is associated with the total creditors account, while Sales Ledger Adjustment Account is associated with the total debtors account. Both matches are correct in the self-balancing ledger system. **Memory cue:** Bought ledger = creditors; Sales ledger = debtors.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"e7b28bbc66afa6a8e452933605679ffd395891f70a08ee2080474a706501bbcc","kind":"pyq"},{"id":"pyq-424","sourceNumber":424,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A machine is purchased for Rs7,00,000. Expenses incurred on its cartage and installation Rs 3,00,000. Calculate the amount of depreciation @ 20% p.a. according to Straight Line Method for the first year ending on 31st March 2022, if this machine is purchased on 1st July 2021.","options":["Rs 1,50,000","Rs 1,40,000","Rs 2,00,000","Rs 1,05,000"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why A is correct — ₹1,50,000:** Machinery cost includes purchase price ₹7,00,000 plus cartage and installation ₹3,00,000 = ₹10,00,000. Annual straight-line depreciation at 20% = ₹2,00,000. The machine was purchased on 1 July, so depreciation for nine months to 31 March = ₹2,00,000 × 9/12 = **₹1,50,000**. **Exam cue:** capitalise installation; prorate depreciation for time in use.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"9390e6ceeddd9cc8bed7ff7c42da9ebfb5e5f93050e36f69c4148a58be45c78e","kind":"pyq"},{"id":"pyq-425","sourceNumber":425,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The Sports Club of Orissa had received in 2022-2023 , ₹2,000 towards subscription. Subscriptions for 2021-22 unpaid on 1 April 2022 were ₹200. Subscriptions paid in advance on 31 March 2022 were ₹50 and the same on 31 March 2023 were ₹40. Subscriptions for 2022-2023 unpaid on 31 March 2023 were ₹90. How will this be reflected in the books of accounts of a non-profit organisation?","options":["Subscription income of ₹1,900 for 2022-23 in the Income and Expenditure Account","Subscription income of ₹1,900 for 2022-23 in the Receipts and Payment Account","Subscription income of ₹2,380 for 2022-23 in the Income and Expenditure Account","Subscription income of ₹2,380 for 2022-23 in the Receipts and Payment Account"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why A is correct — ₹1,900 subscription income:** Income and Expenditure Account uses accrual accounting. Subscription income = cash received ₹2,000 + closing outstanding ₹90 + opening advance ₹50 − opening outstanding ₹200 − closing advance ₹40 = **₹1,900**. The Receipts and Payments Account would show the cash received, ₹2,000, regardless of the accounting period to which it relates. **Exam cue:** current income = receipts + closing outstanding + opening advance − opening outstanding − closing advance.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"7ee5515987b4035e95b6fd6d2f09884173adc68d78d10896d2dcc5ed71d18821","kind":"pyq"},{"id":"pyq-426","sourceNumber":426,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Under the single-entry system when rent is paid, i) it will be recorded in the Cash Book ii) entry will be made in the Rent account Which of the above statements is/are true?","options":["Neither (i) nor (ii)","Only(ii)","Only(i)","Both (i) and (ii)"],"answer":2,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why C is correct — only (i):** In a single-entry system, a rent payment is recorded in the Cash Book because cash/bank changes. A separate Rent Account may not be maintained consistently in the incomplete records, so statement (ii) is not necessarily true. **Exam cue:** single-entry records are incomplete; cash book is one of the main records.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"4ffae1eb834009b6f033e979ac0a07340f028bdc62890ba3b877ebc884dee8fb","kind":"pyq"},{"id":"pyq-427","sourceNumber":427,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the given statements is/are correct in the context of account balances of the Ledger? (i) A debit balance of a personal account means that the party owes that amount to the business. (ii) All real accounts show a debit balance. (iii) Nominal accounts are not usually balanced, but closed by transfer to the Profit and Loss Account, at the time of preparing the final accounts.","options":["Only (i)","Only (ii)","All (i), (ii) and (iii)","Only (ii) and (iii)"],"answer":2,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why C is correct — all three:** A debit balance in a personal account generally indicates that the party owes the business. Real accounts representing assets normally have debit balances, although contra accounts and unusual balances can be exceptions. Nominal accounts are closed to the Profit and Loss Account at period end rather than carried forward as continuing balances. **Exam cue:** personal account debit → debtor; nominal accounts → closed to P&L.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"60de035d72423d1449765669277132fe185094f0ff58f5e99e9d13c3a6501f44","kind":"pyq"},{"id":"pyq-428","sourceNumber":428,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Generally non-profit organisations prepare which of the following? i) Receipt and Payment Account ii) Income and Expenditure Account iii) Balance Sheet","options":["Only (ii)","Only (i)","All (i), (ii) and (iii)","Only (i) and (ii)"],"answer":2,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why C is correct — all three:** Not-for-profit organisations generally prepare a Receipts and Payments Account (cash receipts/payments), an Income and Expenditure Account (accrual-based revenue income and expenses for the period), and a Balance Sheet (assets, liabilities and accumulated fund) at year-end. **Exam cue:** NPO final accounts = R&P + I&E + Balance Sheet.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"7b926b82faf021845d122d903e4f56b60036a65445e8874f17e63a17b9059616","kind":"pyq"},{"id":"pyq-429","sourceNumber":429,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Identify the correct pair of the causes of depreciation with its types.","options":["Passage of time - Internal depreciation","Depletion - External depreciation","Obsolescence - External depreciation","Fire accident - Internal depreciation"],"answer":2,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why C is correct — Obsolescence is external:** Obsolescence occurs when an asset loses usefulness or value because of technological change, market changes or newer alternatives, which is generally an external cause. Passage of time and physical wear are commonly internal/usage-related causes; depletion relates to natural resources. **Exam cue:** new technology/replaced by newer asset → obsolescence.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"c9d170bbf3eff2b67ed3d48820ff7663e56e87f72c7be0e0c761623ca45cc022","kind":"pyq"},{"id":"pyq-430","sourceNumber":430,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In amended cash book, which of the following will be recorded?","options":["Wrong entry pass book","Cheque deposited into bank but not credited b banks","Cheque issued but not presented for payment in banks","Interest allowed b bank credited in the pass book"],"answer":3,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why D is correct:** An amended cash book is updated for items appearing in the passbook but not yet recorded in the cash book, such as bank interest, bank charges, direct collections and standing-instruction payments. Cheques deposited but not yet credited and cheques issued but not yet presented are timing differences, so they are normally dealt with in the Bank Reconciliation Statement, not by amending the cash book. **Exam cue:** bank-recorded item missing from cash book → amend cash book.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"e12185119e5187f91c482e314b13cc613f25598fa1d465ced90afa57a42b5731","kind":"pyq"},{"id":"pyq-431","sourceNumber":431,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A machine is purchased for ₹7,00,000. Expenses incurred on its cartage and installation are ₹3,00,000. Depreciation is charged @ 20% p.a. according to the Straight Line Method for the first year ending on 31 March 2022. Calculate the difference in the amount of depreciation for the $$1^{st}$$ year, if this machine was purchased on 1 April 2021 and if the machine was purchased on 1 July 2021.","options":["₹45,000","₹50,000","₹35,000","₹1,00,000"],"answer":1,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why B is correct — ₹50,000 difference:** Total capitalised cost = ₹7,00,000 + ₹3,00,000 = ₹10,00,000. If purchased on 1 April, full-year depreciation = 20% × ₹10,00,000 = ₹2,00,000. If purchased on 1 July, nine-month depreciation = ₹2,00,000 × 9/12 = ₹1,50,000. Difference = **₹50,000**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"76f9382a57daed26dead109fca3b2072e20bf4ca8f1bc1d2dece8160b833dce4","kind":"pyq"},{"id":"pyq-432","sourceNumber":432,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which option shows the correct accounting treatment given in the nonprofit organization accounting? (i) Small donations - revenue receipts (ii) Subscriptions - revenue receipts","options":["Both (i) and (ii)","Only (ii)","Neither (i) nor (ii)","Only (i)"],"answer":0,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why A is correct — both statements:** Small donations and subscriptions are generally revenue receipts for a not-for-profit organisation, unless a donation is specifically restricted/capital in nature under the applicable accounting policy. Subscriptions are usually recognised as income for the period to which they relate, not simply based on cash received. **Exam cue:** ordinary donations/subscriptions → revenue receipts; specifically capital/endowment donations may differ.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"510acfadae418cf53bed0e719ba04e0e66ed301d7537141e3ca9c3e8a12368ec","kind":"pyq"},{"id":"pyq-434","sourceNumber":434,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A wholly owned subsidiary of the Reserve Bank is responsible for the production of bank notes and manages 2 presses, one each in Mysore and Salboni respectively. What is the name of the subsidiary?","options":["DICGC","BRBNMPL","IFTAS","NABARD"],"answer":1,"source":"SSC CGL Tier-2 Fin&Eco, Aug 2022","explanation":"**Why B is correct — BRBNMPL:** Bharatiya Reserve Bank Note Mudran Private Limited (BRBNMPL) is a wholly owned subsidiary of the Reserve Bank of India involved in banknote production. It operates note presses at Mysuru and Salboni. DICGC provides deposit insurance, IFTAS provides financial technology services, and NABARD focuses on rural/agricultural development finance. **Exam cue:** RBI note printing subsidiary → BRBNMPL.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"2a7672c521d78636d1cbf9a8f5095f9a82e736c291b1cf30573c749dace15607","kind":"pyq"},{"id":"pyq-435","sourceNumber":435,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A Trial Balance may be prepared according to Totals Method and _____ Method.","options":["Deficit","Average","Surplus","Balance"],"answer":3,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why D is correct — Balance Method:** A trial balance can be prepared using the Totals Method or the Balance Method. The totals method lists total debit and credit sides of each ledger account; the balance method lists only each account’s closing debit or credit balance. **Exam cue:** totals method vs balance method.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"d62bc9c0915e0cae6fb4003a9fa448bd72cd351c56743fa148ff3695780293a4","kind":"pyq"},{"id":"pyq-436","sourceNumber":436,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A businessman can find out what his business owns and what it owes from ______.","options":["Profit & Loss A/c","Balance Sheet","Ledger","Trading A/c"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Balance Sheet:** The Balance Sheet reports what a business owns (assets) and what it owes (liabilities), together with the owners’ equity, at a particular date. The Profit and Loss Account reports performance over a period; the Trading Account reports gross profit/loss; the ledger contains individual accounts. **Exam cue:** position at a date → Balance Sheet.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b7a631615e7ae9b46e05641a7a746199282317ede2999a43096c370677d572f9","kind":"pyq"},{"id":"pyq-437","sourceNumber":437,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The maker of a Bill Of Exchange is called the _____.","options":["Payer","Payee","Drawee","Drawer"],"answer":3,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why D is correct — Drawer:** The drawer is the person who makes/draws the bill of exchange and orders the drawee to pay. The drawee is the party directed to pay, and the payee is the person entitled to receive payment. **Memory cue:** drawer writes; drawee pays; payee receives.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"ab49884435832c950cf6d6a62a0400859ea60077c37b7e91de5d559dc60da42e","kind":"pyq"},{"id":"pyq-438","sourceNumber":438,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"_____ system of depreciation is followed in case of those assets which are of small values or where the life of the asset cannot be ascertained with certainty.","options":["Insurance policy","Inventory","Annuity","Sinking fund"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Inventory system:** The inventory system of depreciation is used for low-value, numerous items or assets whose individual useful lives are difficult to determine, such as small tools. The cost of items replaced is charged as they are renewed, subject to the applicable policy. **Exam cue:** small tools/uncertain individual lives → inventory method.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"c7f1d4db04f58b29942dcb195f327f504989701fce895bb61bfac4b3591cf3eb","kind":"pyq"},{"id":"pyq-439","sourceNumber":439,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"If a machine (having a scrap value of Rs.1,000) is purchased for Rs.10,000 and it has an effective life of 10 years of 1000 hours each, what will be the amount of depreciation per hour?","options":["Rs.2.00","Rs.1.50","Re.1.00","Re.0.90"],"answer":3,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why D is correct — ₹0.90 per hour:** Depreciable amount = Cost ₹10,000 − Scrap value ₹1,000 = ₹9,000. Total estimated useful hours = 10 years × 1,000 hours per year = 10,000 hours. Depreciation per hour = ₹9,000 ÷ 10,000 = **₹0.90**. **Formula:** (cost − residual value)/total estimated units or hours.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"d4c96f792ff6ed88f5132b6a91cd321d80c40ad691e9c560221491a054e76bf1","kind":"pyq"},{"id":"pyq-440","sourceNumber":440,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The ______ of a Non-Profit Organisation gives a list of revenue receipts (for past, current and future periods) as well as capital receipts.","options":["Profit & Loss Account","Receipt and Payment Account","Income & Expenditure Account","Profit & Loss Appropriation Account"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Receipts and Payments Account:** This account lists all cash receipts and payments during the period, including revenue and capital items and transactions relating to past, current and future periods. The Income and Expenditure Account includes only revenue income and expenses attributable to the current period on an accrual basis. **Exam cue:** all cash movements/periods → R&P.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b9fe20b456e8bc48e80ad2bbc3f54516f005003dd8df39dc1fd3e0399bb413d3","kind":"pyq"},{"id":"pyq-441","sourceNumber":441,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In case of a Bill of Exchange, ‘Legal Due Date’ is a date which is arrived after adding three days of grace in the _____.","options":["Nominal due date","Date of bill","Date of acceptance","Period of bill"],"answer":0,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why A is correct — Nominal due date:** For a bill of exchange, the nominal due date is calculated from the date/term of the bill. The legal due date is generally the nominal due date plus three days of grace, where grace days apply. **Exam cue:** legal due date = nominal due date + 3 days of grace.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"16a83becac5eacf34f0a2cc48130dd5a443695abdac3e6bfe34386b1c0c0f18b","kind":"pyq"},{"id":"pyq-442","sourceNumber":442,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Self -balancing entries will only be made for those transactions which affect ____.","options":["Three ledgers","One ledger","Four ledgers","Two ledgers"],"answer":3,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why D is correct — Two ledgers:** Self-balancing entries are used for transactions that affect two ledgers and require the respective ledger adjustment accounts to keep the separate ledgers in balance. The adjustment system reconciles inter-ledger entries between the sales/debtors ledger, bought/creditors ledger and general ledger. **Exam cue:** cross-ledger transaction → self-balancing entry.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b74c07ddec50b29d97d163943a801412ec57d0dbc3a91497573cb3c9d7db2cc3","kind":"pyq"},{"id":"pyq-443","sourceNumber":443,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Recording of business transactions are done in a chronological manner in _____.","options":["Journal","Trial Balance","Ledger","Balance Sheet"],"answer":0,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why A is correct — Journal:** Transactions are first recorded in chronological order in the journal or appropriate subsidiary books. The ledger then classifies them account-wise, the trial balance lists ledger balances, and the Balance Sheet reports financial position. **Memory cue:** journal = date-wise; ledger = account-wise.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"006d8c85849b176907a42ac4b54e63585d5986cc55a2c3f73c475a294e3831db","kind":"pyq"},{"id":"pyq-444","sourceNumber":444,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"“Debit all Expenses and Losses, Credit all Gains and Income” is the principle to record journal entry for______ Accounts.","options":["Real","Personal","Artificial","Nominal"],"answer":3,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why D is correct — Nominal accounts:** The traditional rule for nominal accounts is “Debit all expenses and losses; credit all incomes and gains.” Real accounts follow “Debit what comes in, credit what goes out,” while personal accounts follow “Debit the receiver, credit the giver.” **Memory cue:** nominal = expenses/losses debit, income/gains credit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"2fd93e9b79bdf279f29ae83a04106d084d100c37a0a525eaec70863c1c193ceb","kind":"pyq"},{"id":"pyq-445","sourceNumber":445,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"_____ is / are charged to the Profit & Loss Account.","options":["Stock","Trade expenses","Import Duty","Royalty"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Trade expenses:** Trade/operating expenses are generally charged to the Profit and Loss Account as expenses of running the business. Stock is an asset/inventory balance, import duty may form part of inventory or asset cost depending on what is imported, and royalty treatment depends on whether it is a production cost, operating expense or capitalised right. **Source note:** the question’s wording is broad; this follows its intended classification.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b3e4dfc6ee4c452c83060ee4ffcc3eb3e8aa22ed5f54bf1fa4ec1ef75290daef","kind":"pyq"},{"id":"pyq-446","sourceNumber":446,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"When a number of transactions on the same date or relating to one particular account/nature are recorded by means of a single journal entry, such an entry is called as ____.","options":["Contra Entry","Compound Journal Entry","Rectification Entry","Adjustment Entry"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Compound Journal Entry:** A compound journal entry records multiple debits and/or credits in a single entry for related transactions. A contra entry records transfers between cash and bank; a rectification entry corrects an error; an adjustment entry records period-end adjustments such as accruals or prepayments. **Exam cue:** multiple accounts in one journal entry → compound entry.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"46975c6ecaeb01ed295a4d2a16c71d593d88a0031bc22201c8a7aefbf649340f","kind":"pyq"},{"id":"pyq-447","sourceNumber":447,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"If the account of Mr.Jay was debited by Rs.495 instead of being credited by Rs.459, the rectification will be done by_____.","options":["Crediting his account by Rs.594","Debiting his account by Rs.954","Crediting his account by Rs.954","Debiting his account by Rs.594"],"answer":2,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why C is correct — Credit by ₹954:** The account was wrongly debited ₹495 but should have been credited ₹459. To cancel the incorrect debit, credit ₹495; to record the correct credit, credit another ₹459. Total correcting credit = ₹495 + ₹459 = **₹954**. **Exam cue:** wrong debit and required credit → both corrections point to credit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"ffbf3426222b3de1c346a18286c511542c44a65c78a898172929e59a878d471f","kind":"pyq"},{"id":"pyq-448","sourceNumber":448,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The technique of finding out the net balance of a ledger account, after considering the totals of both debit and credit sides, is known as _____.","options":["Rectification of an Account","Comparison of an Account","Balancing of an Account","Reconciliation of an Account"],"answer":2,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why C is correct — Balancing an account:** Balancing means comparing the totals of the debit and credit sides of a ledger account and finding the difference, which becomes the closing balance carried down. Rectification corrects errors; reconciliation compares two records; comparison is a broader term. **Exam cue:** total both sides and find the difference → balance the account.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"63a80fc23039ba9eb5948089e3408d535a31ec24ab024812c38e09c9818e9e9e","kind":"pyq"},{"id":"pyq-449","sourceNumber":449,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The funds raised by Non-Profit Organisations are credited to capital fund or ______.","options":["Special Revenue Fund","Reserve Fund","General Fund","Debt Service Fund"],"answer":2,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why C is correct — General Fund:** Funds raised by a not-for-profit organisation are generally accumulated in its capital fund/general fund, depending on the organisation’s constitution and reporting terminology. Specific-purpose receipts may be recorded in a special fund. **Exam cue:** general accumulated fund of NPO → General Fund/Capital Fund.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"f1c1a048974d15facfa6f93be0af64931459cfbf43ab97cd23134926661ac47c","kind":"pyq"},{"id":"pyq-450","sourceNumber":450,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Wages paid for erection of a new plant or machinery are taken as _____.","options":["Revenue Expenditure","Capital Expenditure","Deferred Capital Expenditure","Deferred Revenue Expenditure"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Capital expenditure:** Wages incurred to erect and install a new plant or machinery are directly attributable to bringing the asset to the location and condition necessary for it to operate. They are therefore included in the asset’s cost rather than charged as routine revenue expenditure. **Exam cue:** installation/erection wages → capitalise with machinery.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"a92486d9ae341c021dbba3693031336f5f761354247b8b0500025a35143a67ff","kind":"pyq"},{"id":"pyq-451","sourceNumber":451,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The objective of preparing a Bank Reconciliation Statement is to _____.","options":["Rectify the errors of pass book","Idenify difference between balance of bank statement and the cash book","Rectify the errors of trial balance","Rectify the errors of cash book"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct:** A Bank Reconciliation Statement explains the difference between the bank balance shown by the Cash Book and the balance shown by the bank statement/passbook at a particular date. It does not itself correct errors; errors are corrected in the relevant books, and timing differences are reconciled. **Exam cue:** BRS explains/reconciles the difference, not automatically rectifies it.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"The objective of preparing a Bank Reconciliation Statement is to _____.","options":["Rectify the errors of pass book","Idenify difference between balance of bank statement and the cash book","Rectify the errors of trial balance","Rectify the errors of cash book"],"answer":1,"explanation":"**Why B is correct:** A Bank Reconciliation Statement explains the difference between the bank balance shown by the Cash Book and the balance shown by the bank statement/passbook at a particular date. It does not itself correct errors; errors are corrected in the relevant books, and timing differences are reconciled. **Exam cue:** BRS explains/reconciles the difference, not automatically rectifies it.","revision":"original","contentSignature":"438a82b75ac71c8b2d5b1cac05afe6a0eb7f6904c614901b50b91b2002369f84"}],"contentSignature":"438a82b75ac71c8b2d5b1cac05afe6a0eb7f6904c614901b50b91b2002369f84","legacySubject":"financial-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-452","sourceNumber":452,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"If the balance as per Cash Book is Rs.5,800; cheques amounting to Rs.2,000 are issued but not yet presented; cheques of Rs.1,500 sent for collection, but not yet collected, and amount of Rs.200 is wrongly debited by the bank, what will be the balance as per Pass Book?","options":["Rs.1,700","Rs.7,800","Rs.6,100","Rs.2,800"],"answer":2,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Verified calculation:** Starting from the Cash Book balance ₹5,800, add cheques issued but not yet presented ₹2,000, then subtract cheques sent for collection but not yet collected ₹1,500. The bank has wrongly debited ₹200 in the Pass Book, so that error is subtracted when reconciling from Cash Book to Pass Book: ₹5,800 + ₹2,000 − ₹1,500 − ₹200 = **₹6,100 (option C)**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","auditStatus":"verified-explanation","auditNote":"Calculation checked against published copies of the SSC CGL Tier-2 AAO question; answer remains Option C.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"75ff48e7c5179b7490544c0dae6ab2c28f32ce8b6ed6d003f4070d3e684f58fa","kind":"pyq"},{"id":"pyq-453","sourceNumber":453,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"According to Section 5 of the Negotiable Instruments Act, 1881, a _____ is defined as, an instrument in writing containing an unconditional order, signed by the maker, directing a certain person, to pay a certain sum of money only to, or to the order of, certain person or to the bearer of the instrument.","options":["Letter of Credit","Cheque","Demand Draft","Bill of Exchange"],"answer":3,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why D is correct — Bill of Exchange:** Section 5 of the Negotiable Instruments Act, 1881 defines a bill of exchange as a written instrument containing an unconditional order, signed by the maker, directing a certain person to pay a certain sum of money to a specified person, their order or bearer as permitted by law. A cheque is a specific kind of bill of exchange drawn on a banker and payable on demand. **Exam cue:** unconditional written order to pay → bill of exchange.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"9dea37937b87f6d9135035204b73abcd6372195366264f4d76fa8751e927de6b","kind":"pyq"},{"id":"pyq-454","sourceNumber":454,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which one of the following entry will be passed for ‘credit sales’ under self balancing ledger system?","options":["Debtors Ledger Adjustment A/c ----Dr. To General Ledger Adjustment A/c","Cash A/c ---- Dr. To Individual Customer A/c","General Ledger Adjustment A/c ---- Dr. To Debtors Ledger Adjustment A/c","Individual Customer A/c ---- Dr. To Sales A/c"],"answer":0,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why A is correct:** Under the self-balancing ledger system, a credit sale affects the individual debtor’s account and the sales ledger total. The debtor ledger adjustment account is debited and the general ledger adjustment account credited to keep the separate ledgers in balance under the system’s control-account conventions. **Exam cue:** credit sale increases debtors; self-balancing entries mirror the ledger totals.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"4429bd3f0b472adff20c262306350f2df8e9d58ed1607ffa2b8040c8619d62b1","kind":"pyq"},{"id":"pyq-455","sourceNumber":455,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which one of the following is an element of capital account in the Balance of Payments?","options":["Income from foreign tourists","Foreign direct investments","Royalties from patents","Export income"],"answer":1,"source":"SSC CGL Tier-2 AAO, Sep 2019","explanation":"**Why B is correct — Foreign direct investment:** Foreign direct investment is an international investment flow, classified in the capital/financial account in the older exam terminology. Tourism receipts, patent royalties and export income are current-account items, generally recorded as services or goods/income flows depending on the transaction. **Source-era note:** modern balance-of-payments manuals distinguish the capital account from the financial account more precisely.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"bafa98813dafe2bdf2a655c55f45dcca2e621d31706af0ebf756f906f7bbbc38","kind":"pyq"},{"id":"pyq-456","sourceNumber":456,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following truly describe govt. intervention in the MSME space in view of Covid-19 pandemic? I. Provisioning of collateral free automatic loans worth Rs.3 lakh crores. II. Provision of 100% guarantee coverage to banks and NBFCs on principal and interest for loans to NBFCs. III. Redefined MSMEs to include both investment and turnover criteria. IV. Created a war chest of Rs. 3,00,000 crores for the MSMEs loans and employment protection. V. Allocated Rs. 3,00,000 crores for the MSMEs loan moratorium and waiver. Choose the correct answer from the options given below:","options":["I, II, III only","II, III, IV only","III, IV, V only","I, III, IV only"],"answer":0,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why A is correct — I, II and III:** India’s COVID-era MSME package included collateral-free automatic loans, government guarantee coverage for eligible loans to MSMEs/NBFC-linked channels, and a revised MSME definition using both investment and turnover criteria. The claim of a separate ₹3 lakh crore war chest and a ₹3 lakh crore loan moratorium/waiver is not an accurate description of the scheme as worded. **Historical policy note:** answer according to the 2020 package described by the source.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"497c8ae662a494f1259367a9d1ce83ec5120dcc15b6ab818f40caa17672d7417","kind":"pyq"},{"id":"pyq-457","sourceNumber":457,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Sequence the following CSR eligibility criteria and spending as per the provisions of the Indian Companies Act 2013. I. Positive net worth of Rs. 500 crores or more II. Two percent of average profit spends on CSR III. Net profit of Rs. 5 crore or more in given financial year IV. Turnover of Rs. 1,000 crore or more V. Penal action for non-compliance Choose the correct answer from the options given below","options":["V, II, IV, III, I","II, V, I, III, IV","I, IV, III, II, V","III, II, I, IV, V"],"answer":2,"source":"UGC NET Commerce, Oct 2020","explanation":"**Correct sequence: option C — I, IV, III, II, V.** CSR provisions work in this order: first the eligibility thresholds (net worth, turnover and net profit), then the 2%-of-average-net-profit spending requirement, and finally the consequences of non-compliance.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","auditStatus":"corrected-key","auditNote":"Answer corrected to Option C after checking the published UGC NET Commerce 17 Oct 2020 Shift 2 key.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"ee4ef34b7a9ef566bdf38da0f94af22652843d1b9118980a8fb0030591f9f0cf","kind":"pyq"},{"id":"pyq-459","sourceNumber":459,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Given below are two statements: One is labelled as Assertion A and the other is labelled as Reason R: Assertion A: Credit flows to agriculture and SME sector have increased in recent years Reason R: Reserve Bank of India has gradually relaxed various controls in credit market. In the light of the above statements, choose the most appropriate answer from the options given below:","options":["Both A and R are correct and R is the correct explanation of A","Both A and R are correct but R is NOT the correct explanation of A","A is correct but R is not correct","A is not correct but R is correct"],"answer":0,"source":"UGC NET Commerce, Oct 2020","explanation":"**Assertion–reason:** Both statements are true, and the reason explains the assertion (option A). Credit availability to agriculture and small enterprises is influenced by RBI policy, directed-lending rules and credit-market regulation. The assertion’s phrase “increased in recent years” is time-specific, so read it in the exam’s period context. **Exam cue:** policy easing and credit reforms support sectoral credit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"ae6030ed9f02fbc59b84c17214fee06c4ffd5739b5e35ff69c1718ab7d60a0ca","kind":"pyq"},{"id":"pyq-460","sourceNumber":460,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Given below are two statements: One is labelled as Assertion A and the other is labelled as Reason R: Assertion A: TRIMs and TRIPs provisions facilitate and promote FDI Reason R: TRIMs and TRIPs provisions remove restrictions and address capital flow. In the light of the above statements, choose the most appropriate answer from the options given below:","options":["Both A and R are correct and R is the correct explanation of A","Both A and R are correct but R is NOT the correct explanation of A","A is correct but R is not correct","A is not correct but R is correct"],"answer":0,"source":"UGC NET Commerce, Oct 2020","explanation":"**Source-checked answer: Option A.** The published UGC NET Commerce 17 Oct 2020 Shift 2 version keys this as “Both A and R are correct and R is the right explanation of A.” The supplied question bank had answer index 1 (Option B), which conflicts with that published key. Note: online copies differ in the wording of Option D, so preserve this question's exact source version if the original paper becomes available.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","auditStatus":"corrected-key","auditNote":"Answer changed from Option B to Option A to match the published UGC NET Commerce 17 Oct 2020 Shift 2 key; source copies show a minor option-wording variant.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"4b76cbbbc02bff51168c0b85e86938fe848e773ec6dcd9d4675e2087347837e1","kind":"pyq"},{"id":"pyq-461","sourceNumber":461,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which one is False as per the relevant provisions of Indian Contract Act, 1872?","options":["A void agreement is one that is not enforceable by law.","Assignment is the obvious mode of discharge of contract.","Where a party waives its rights under the contract, the other party is released of its obligations under the contract.","Where the subject matter of a contract is destroyed for no fault of the promisor, the contract does not become void by impossibility of performance."],"answer":1,"source":"UGC NET Commerce, Oct 2020","explanation":"Assignment can transfer contractual rights but does not automatically discharge all contractual obligations; consent/novation may be required to transfer duties. A void agreement is unenforceable, and destruction of the subject matter without fault can make performance impossible and discharge the contract. The wording of statement D (“does not become void by impossibility”) also appears false, so more than one option may be problematic. **Flag: the stem/options may be corrupted; check the original paper.**","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","auditStatus":"needs-review","auditNote":"This question's explanation flags a key/options/source ambiguity. Verify the original exam wording before memorising the supplied answer.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"5d89f14128d9a1d596958b4935c093261a540f49cab9a1c989cebe5c7d11048d","kind":"pyq"},{"id":"pyq-462","sourceNumber":462,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following is not a resource-imbalance model of burnout?","options":["Job demands-resources model","Conservation of resources model","Three dimensional model","Areas of Work life model Answer Question No. 96 to 100 on the basis of the following passage: It is desirable for consumers to be aware of their rights, and to exercise those rights responsibly and intelligently. In these days of audio-video publicity on the public and private media, it is indeed very difficult, if not impossible, to verify the exaggerated or false claims made by producers, manufacturers, distributors and dealers of various goods and services. The all- pervasive, exaggerated and often false claims, made for services and goods, emphasize the imperative need for Consumer Protection Legislation and creation of awareness about it among the general public. In this connection, there are a number of enactments, in India such as the prevention of Food Adulteration Act, 1954, the Essential Commodities Act, 1955, the Hire Purchases Act, 1972,the Standards Weight and Measure Act, 1976 etc. However, the remedies prescribed there under are time-consuming, inadequate and expensive. As in other areas of Judicial Processes, the offenders are hardly caught, proceeded against and rarely, if ever, got convicted. When violators go scot-free, the victims have no remedy and gets frustrated."],"answer":2,"source":"UGC NET Commerce, Oct 2020","explanation":"**Why C is correct — Three-dimensional model:** The Job Demands–Resources model, Conservation of Resources model and Areas of Worklife model are commonly framed around demands/resources or mismatches between people and work conditions. The three-dimensional model of burnout describes dimensions such as exhaustion, cynicism/depersonalisation and reduced professional efficacy, rather than being a resource-imbalance model in the same classification. **Exam cue:** burnout dimensions ≠ resource-imbalance model.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"6f9258bfc92c6a9913a82860f31237f3a16c8c109c48631de9ada00b58cb8d05","kind":"pyq"},{"id":"pyq-463","sourceNumber":463,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following forms may not result in credit risk? 1. Principle and/or interest amount may not be repaid in the case of direct lending. 2. In case of guarantees or letter of credit, fund may not be forth coming from the constituents upon crystallization of the liability. 3. Funds/ Securities settlement may not be effected, in case of securities trading business. 4. Provide information for determining adequacy of loan loss provision. Choose the correct answer from the options given below.","options":["1, 2 and 3 only","1, 3 and 4 only","2 and 3 only","4 only"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is correct — statement 4:** Non-repayment of principal/interest, failure to honour a guarantee/letter of credit and settlement failure in securities transactions are examples of credit/counterparty risk. “Provide information for determining adequacy of loan loss provision” is a purpose of risk information/reporting, not itself a form of credit risk. **Exam cue:** failure to pay/settle → credit risk; provisioning information → risk-management process.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"34708ff335bd0372f6425c2fe821174bf037a188a52c85d414543ee7380f64b8","kind":"pyq"},{"id":"pyq-464","sourceNumber":464,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Experimental characteristics/factors influencing distribution decisions are: (1) Government policy (2) State of economy (3) Social activism (4) Technological and infrastructure developments (5) Statutory provisions Choose the correct answer from the options given below:","options":["1 and 4 only","2, 3 and 5 only","1, 3 and 4 only","1, 2, 4 and 5 only"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is correct — 1, 2, 4 and 5:** Government policy, the state of the economy, technology/infrastructure and statutory provisions can all influence distribution decisions. Social activism is not included in the source’s selected combination. **Exam note:** the wording “experimental characteristics” may be a transcription error; use the original source framing for strict recall.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"a8b33aea99840c35fce6c72ab716c5c755e247c43166e819589a1097d6520820","kind":"pyq"},{"id":"pyq-465","sourceNumber":465,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Companies strive to stockpile internally generated cash. Such a cash reserve is called","options":["Margin of safety","Financial float","Reserve float","Financial slack"],"answer":3,"source":"UGC NET Commerce, Nov 2021","explanation":"**Why D is correct — Financial slack:** Financial slack refers to internally generated or readily available financial resources held by a company to support future investments, absorb shocks or take advantage of opportunities. It can include cash reserves and unused borrowing capacity. **Exam cue:** reserve of financial flexibility → financial slack.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"a7a9dc580068c76901fb335f1c6b30f23c8d0dc524a6e31e676c1adc856b6fb8","kind":"pyq"},{"id":"pyq-466","sourceNumber":466,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which one of the following is correct regarding the Negotiable Instruments Act in India?","options":["A cheque is always drawn on a banker.","A cheque requires the acceptance by the drawee.","A bill of exchange can be drawn payable to bearer on demand.","A promissory note containing a conditional promise to pay is a valid promissory note."],"answer":0,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why A is correct:** A cheque is a bill of exchange drawn on a specified banker and payable on demand. It does not require acceptance by the drawee bank in the same way an ordinary time bill may be accepted. A bill of exchange cannot generally be made payable to bearer on demand under the statutory restrictions, and a promissory note must contain an unconditional promise to pay. **Exam cue:** cheque → always drawn on a banker.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"91d22b09eeb5a0818a866354af3a1041c34cd706906d81e57681e5efd6193989","kind":"pyq"},{"id":"pyq-467","sourceNumber":467,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A project requires an initial investment of Rs. 56,125 and its estimated salvage value is Rs. 3,000. The annual estimated income after depreciation and tax for its entire life of 5 years are Rs. 3,375, Rs. 5,375, Rs. 7,375, Rs. 9,375 and Rs. 11,375 respectively. Which one of the following is its average rate of return?","options":["24.9%","124.74%","29.94%","60.88%"],"answer":0,"source":"UGC NET Commerce, Oct 2022","explanation":"**Verified calculation:** Average annual income = (₹3,375 + ₹5,375 + ₹7,375 + ₹9,375 + ₹11,375) ÷ 5 = ₹7,375. Average investment = salvage value + ½(cost − salvage value) = ₹3,000 + ½(₹56,125 − ₹3,000) = ₹29,562.50. ARR = ₹7,375 ÷ ₹29,562.50 × 100 ≈ **24.9% (option A)**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","auditStatus":"corrected-key","auditNote":"Corrected Option A from 26.28% to 24.9% and answer index to A after checking the published UGC NET Commerce 14 Oct 2022 Shift 1 question.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"2bf4560bc9458960309ec995e9981ead7314d97fa92089283b30915408c835fd","kind":"pyq"},{"id":"pyq-468","sourceNumber":468,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which is the most appropriate mode of entry in international business to an enterprise with little experience of International Markets?","options":["Acquisition","Exporting","Strategic Alliance","Joint Venture"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct — Exporting:** Exporting is often the lowest-commitment entry mode for an enterprise with limited international experience. It allows the firm to test demand and learn about foreign markets without the large capital commitment and managerial risk of acquisition, joint venture or direct investment. **Exam cue:** least experience/commitment → exporting.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b61d0360d75290d27cbd1302d4b49ef23eaf7f97ddf842702155b42ede8b2812","kind":"pyq"},{"id":"pyq-469","sourceNumber":469,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In which one of the following modes of entry into foreign markets risk and profit potential are the highest?","options":["Indirect exporting","Joint venture","Direct investment","Direct exporting"],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — Direct investment:** Direct investment requires the firm to commit capital and management resources in the foreign market, exposing it to substantial operating, political, currency and market risks. It can also provide greater control and profit potential than indirect/direct exporting or a joint venture, depending on the structure. **Exam cue:** highest control, risk and potential return → direct investment.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"8c6a2a59ca2627aa1633651225f256567e098b03659144c069f1e41d63a0940e","kind":"pyq"},{"id":"pyq-470","sourceNumber":470,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statement(s) are correct? a. Asset liability management is a mechanism to address the risk arising due to mismatch of assets and liabilities. b. Non-performing Assets (NPA) must be written off as loss in the financial year in which NPA has been identified. c. Undisclosed reserves are included in capital of banks (Tier II) if they represent accumulation of post-tax profits. d. Bank cannot accept deposits from the public for a period exceeding five years. e. Hybrid debt capital instruments may be included in Tier II capital. Choose the correct answer from the options given below:","options":["a, c, d only","c, d, e only","b, c, d only","a, c, e only"],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — a, c and e:** Asset-liability management addresses risks from maturity, interest-rate and liquidity mismatches. Undisclosed reserves may count in Tier II capital only when they meet the relevant prudential criteria, and qualifying hybrid debt capital instruments may also be included in Tier II. NPA treatment is not simply an automatic write-off in the year identified, and the claim that banks cannot accept public deposits for more than five years is not generally correct as stated. **Banking-regulation note:** capital rules change; use the relevant RBI framework for current compliance.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"5c4a237ba10765b4a00004f6cf3c65f8e0c2f312abe5a2e6f4af3db12ce6c110","kind":"pyq"},{"id":"pyq-472","sourceNumber":472,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Match List I with List II: List I (Accounting Standard) a. Ind-AS: 1 b. Ind-AS: 8 c. Ind-AS: 28 d. Ind-AS: 34 List II (Description) i. Investments in Associates and Joint ventures ii. Presentation of Financial Statements iii. Interim Financial Reporting iv. Accounting policies, changes in Accounting Estimates and Errors. Choose the correct answer from the options given below:","options":["a- ii, b- iii, c- i, d- iv","a- ii, b- iv, c- i, d- iii","a- iii, b- ii, c- iv, d- i","a- iii, b- iv, c- i, d- ii"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct:** Ind AS 1 covers Presentation of Financial Statements (a–ii); Ind AS 8 covers Accounting Policies, Changes in Accounting Estimates and Errors (b–iv); Ind AS 28 covers Investments in Associates and Joint Ventures (c–i); and Ind AS 34 covers Interim Financial Reporting (d–iii). **Memory cue:** 1 = presentation; 8 = policies/errors; 28 = associates/JVs; 34 = interim.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"52788ec369242ccb3776cd993020605bb2a5cb053dbd91ca796a287d040a2198","kind":"pyq"},{"id":"pyq-473","sourceNumber":473,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which one of the following is an example of Secondary Reserves?","options":["Cash in hand and balances with other banks in current account.","Balances with RBI for CRR.","Investment in Commercial Paper.","Investment in Government Securities for SLR."],"answer":2,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why C is correct — Investment in Commercial Paper:** In traditional banking terminology, secondary reserves are liquid interest-earning assets held in addition to primary reserves, such as short-term marketable securities including commercial paper. Cash and balances with other banks/current balances at RBI are primary liquidity/reserve assets; government securities held to meet SLR are statutory liquidity investments. **Exam cue:** secondary reserves = short-term liquid investments beyond primary cash reserves.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"18c49c38bcde2ccb1f5f5d807102ed95d981637eaea3f29eded65b557d7af157","kind":"pyq"},{"id":"pyq-474","sourceNumber":474,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Under which one of the following the Basel framework places restrictions on participation by banks in system-wide credit booms with the aim of reducing their losses in credit bust?","options":["Catastrophic Reserve Capital.","Countercyclical Capital Buffer.","Deferred Capital.","Conservative Preference Capital."],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct — Countercyclical Capital Buffer:** The Basel framework’s Countercyclical Capital Buffer (CCyB) aims to build extra capital during periods of excessive credit growth and allow that buffer to be drawn down during a downturn. This helps reduce the procyclical effect of lending and strengthens banks against losses when the credit cycle turns. **Exam cue:** boom → build buffer; bust → release buffer.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"32cd719d77bb1788fcf87d4006a1ceb3afe04ebdf19082c9cd68304d47842570","kind":"pyq"},{"id":"pyq-475","sourceNumber":475,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following are key features of prudent accounting concepts and conventions? (a) It includes revenues and profits in the accounts when they are realised. (b) It prevents profits from being overstated. (c) It prevents a trader from more withdrawing from the business than is wise. (d) Managerial efficiency and expertise. (e) Good customer relations. Choose the most appropriate answer from the options given below:","options":["c, d and e only.","a, d and e only.","b, c and d only.","a, b and c only."],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — a, b and c:** Prudence/conservatism recognises revenue when it is realised under the relevant rules, avoids overstating profit and encourages caution in distributions/withdrawals so the business’s financial position is not overstated. Managerial efficiency and good customer relations are useful business qualities but are not features of the prudence accounting convention. **Exam cue:** prudence = caution in recognising gains and losses.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"04226efc832b45c4ff95808c3c6493f638a9c6ff683724b4554859275cb850c5","kind":"pyq"},{"id":"pyq-476","sourceNumber":476,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Match List I with List II: List I (Personality Factor): (a) Warmth (b) Abstractedness (c) Openness to change. (d) Perfectionism List II (Bipolar Dimension): (i) Imaginative vs practical. (ii) Controlled vs casual. (iii) Outgoing vs reserved. (iv) Experimental vs conservative. Choose the correct answer from the options given below:","options":["a- ii, b- i, c- iv, d- iii","a- iii, b- i, c- iv, d- ii","a- i, b- iv, c- iii, d- ii","a- iii, b- ii, c- iv, d- i"],"answer":1,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why B is correct:** These are dimensions from the 16PF personality framework: warmth = outgoing vs reserved (a–iii); abstractedness = imaginative vs practical (b–i); openness to change = experimental vs conservative (c–iv); perfectionism = controlled vs casual (d–ii). **Memory cue:** warmth → sociability; abstractedness → imagination; change → experimentation; perfectionism → control.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"61ef0b4ead985b869a3179756143122be2b50664489c2846fb0fca31be962c43","kind":"pyq"},{"id":"pyq-477","sourceNumber":477,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Currency depreciation in the Indian rupee times has largely been attributes to: A. Declining domestic savings B. Increasing FDI flows C. Portfolio outflows D. Higher currency circulation E. Higher imports and debt servicing Choose the correct answer from the options given below:","options":["A, B and C","B, C and D","A and D","C and E"],"answer":3,"source":"UGC NET Commerce, Oct 2022","explanation":"**Why D is correct — C and E:** Portfolio outflows can increase demand for foreign currency and put downward pressure on the rupee. Higher imports and debt-servicing payments also create demand for foreign currency. Higher FDI inflows would ordinarily support foreign-currency supply rather than directly explain depreciation. **Exam cue:** capital outflows + import/debt-payment demand → pressure on domestic currency.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"1f3655ee923db690d4c3e26c7221a30c176bb4302feaf3fa9721a73706c7538a","kind":"pyq"},{"id":"pyq-478","sourceNumber":478,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which one of the following is NOT true?","options":["Capital expenditure results in extra capacity.","Capital expenditure results in a benefit which will last for a long time.","Capital expenditure results in the acquisition of a permanent asset.","Heavy expenditure on advertisement campaigns in order to introduce a new product in the market."],"answer":0,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why A is correct — not always true:** Capital expenditure usually creates or improves a long-term asset and provides benefits over multiple periods, but it does not always increase productive capacity; replacing an existing asset may simply maintain capacity or efficiency. A major advertising campaign to launch a new product has traditionally been discussed as deferred revenue expenditure in some exam texts, though modern accounting generally expenses advertising when incurred unless specific asset-recognition criteria are met. **Exam cue:** capital expenditure need not always add capacity.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"44e0cc3fcfa64b44424bf1d34a5632be640012ed796313f909e108e8bae5d86e","kind":"pyq"},{"id":"pyq-479","sourceNumber":479,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A Vertical Marketing System (VMS) combining successive stages of production and distribution under single ownership, is known as:","options":["Corporate VMS.","Administered VMS.","Contractual VMS.","Conventional VMS."],"answer":0,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why A is correct — Corporate VMS:** A corporate vertical marketing system combines successive stages of production and distribution under single ownership. An administered VMS is coordinated by the power/size of one channel member, while a contractual VMS coordinates independent firms through formal agreements. **Exam cue:** single ownership across stages → corporate VMS.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"8fa2f7308abe119bac32760f71dd8c0f3f621d44986b367073ff4a271e9d2ea1","kind":"pyq"},{"id":"pyq-480","sourceNumber":480,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Revenue expenditure of the Central government includes: A Debt relief to farmers. B. Subsidy for fertilizers. C. Grants to states. D. Central plan allocations for rural development. E. Central plan allocation for irrigation and flood control. Choose the correct answer from the options given below: Codes","options":["A, B and E only","A, C and D only","C, D and E only","A, B and C only"],"answer":3,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why D is correct — A, B and C:** Debt relief to farmers, fertilizer subsidies and grants to states are generally classified as revenue expenditure in the government-budget context of this question. Allocations for irrigation and flood control may create durable assets and are generally treated as capital expenditure when used for asset creation. **Exam cue:** subsidies/grants/current relief → revenue; asset-creating infrastructure → capital.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"d0203ae9b64e62bdc0a31bc1a0f11ac812ebaecc9058274ce0f6f00ff21cf9f6","kind":"pyq"},{"id":"pyq-481","sourceNumber":481,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following are the off-balance sheet source(s) of finance? A. Securitisation B. Factoring C. Forfaiting D. Operational lease E. Credit rating Choose the correct answer from the options given below: Codes","options":["A and E only","B, C and E only","A, B and C only","A, B, C and D only"],"answer":3,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why D is correct — A, B, C and D:** Securitisation, factoring, forfaiting and operating leases can be used as alternative financing arrangements that may keep certain assets/obligations off the balance sheet depending on the applicable accounting rules and transfer/lease terms. A credit rating assesses creditworthiness; it is not itself a financing source. **Accounting note:** modern standards may require recognition of lease assets/liabilities, so “off-balance sheet” is framework- and contract-dependent.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"9f1b72bdc74193d5b655aaad7c816f193b57c712e33a001a5dc60b378b87027c","kind":"pyq"},{"id":"pyq-482","sourceNumber":482,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Match List I with List II: List I (Ind AS) A. Ind AS 37 B. Ind AS 104 C. Ind AS 2 D. Ind AS 19 List II (Topic (Subjects)) I. Insurance contracts II. Inventories III. Provisions, Contingent Liabilities and Contingent Assets IV. Employee Benefits Choose the correct answer from the options given below: Codes","options":["A- III, B- I, C- II, D- IV","A- I, B– II, C- III, D- IV","A- IV, B- III, C- II, D- I","A- II, B- III, C- I, D- IV"],"answer":0,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why A is correct:** Ind AS 37 covers Provisions, Contingent Liabilities and Contingent Assets (A–III); Ind AS 104 historically covered Insurance Contracts (B–I); Ind AS 2 covers Inventories (C–II); and Ind AS 19 covers Employee Benefits (D–IV). **Standards note:** insurance-contract standards may have changed or been replaced in later frameworks; this is the source’s listed Ind AS mapping.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"06151892395e374308d37d120b8464e035ae669cb3ee862c3735aab5a88e8e71","kind":"pyq"},{"id":"pyq-484","sourceNumber":484,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following are the functions of Reserve Bank of India? A. Issue of Currency B. Accepting Deposits C. Banker of Government D. Bankers Bank E. Credit Control Choose the correct answer from the options given below: Codes","options":["B and C only","A and D only","A, B, C and D only","A, C, D, and E only"],"answer":3,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why D is correct — A, C, D and E:** RBI functions include issuing currency, acting as banker to the government, serving as banker’s bank and conducting monetary/credit control. Accepting ordinary public deposits is not a core central-bank function in the way it is for commercial banks. **Exam cue:** central bank → currency, government banking, banker's bank, credit control.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"6ffb602368a17f04454ed1d6848d45654ec3ecc9d262646b8420e0ce764f4db4","kind":"pyq"},{"id":"pyq-485","sourceNumber":485,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Arrange the following examples of human needs in the hierarchy of their increasing importance. a. Insurance for accidents. b. Recognition and respect from others. c. Food and shelter provisions. d. Accomplishing distinction in chosen area by maximising potential. e. Developing meaningful relations with others. Choose the correct answer from the options given below: Codes","options":["a, c, e, b, d","c, a, b, e, d","a, c, e, d, b","c, a, e, b, d"],"answer":3,"source":"UGC NET Commerce, Mar 2023","explanation":"**Why D is correct — c, a, e, b, d:** Maslow’s hierarchy rises from physiological needs (food and shelter, c), to safety (insurance against accidents, a), social/belonging needs (meaningful relations, e), esteem (recognition and respect, b), and self-actualisation (maximising potential, d). **Memory cue:** physiological → safety → social → esteem → self-actualisation.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"6fd818fdc31fa36b7fa2973cb9c202b1e222fc0249b291db9b3bb144f096204e","kind":"pyq"},{"id":"pyq-486","sourceNumber":486,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Given below are two statements: One is labelled as Assertion A and the other is labelled as Reason R. Assertion A: When a partner retires, all the assets and liabilities are revalued according to current value. Reason R: The balance sheet should show the correct values of assets and liabilities. In the light of the above statements, choose the most appropriate answer from the options given below:","options":["Both A and R are correct and R is the correct explanation of A","Both A and R are correct but R is not the correct explanation of A","A is correct but R is not correct","A is not correct but R is correct"],"answer":1,"source":"UGC NET Commerce, Jun 2023","explanation":"**Source-checked answer: Option B.** Both statements are generally treated as correct, but the reason does not fully explain why revaluation is undertaken specifically at retirement. Revaluation helps establish the profit/loss on changes in asset and liability values and allocate that change among partners in their old profit-sharing ratio before settlement. The published UGC NET Commerce answer is “Both A and R are correct but R is NOT the correct explanation of A.”","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"answer-key-review","auditStatus":"verified-key","auditNote":"Answer index B matches the published UGC NET Commerce June 2023 question key; explanation clarified from source.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"6784d72af51b804d2c11371da420a4cbf88265df8dfec0f598495e15ed31ffc6","kind":"pyq"},{"id":"pyq-487","sourceNumber":487,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Insurance claim received on account of machinery damaged completely by fire is","options":["Capital Receipt","Revenue Receipt","Capital Expenditure","Revenue Expenditure"],"answer":0,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why A is correct — Capital receipt:** Insurance compensation for machinery destroyed by fire relates to the loss of a capital asset, so it is generally treated as a capital receipt in the conventional classification used in this question. Any difference between the asset’s carrying amount and insurance proceeds is accounted for separately as a gain/loss on disposal or destruction. **Exam cue:** compensation for destroyed fixed asset → capital receipt.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"5608b72fb93bf61a659cc4a9e7839ddeb497901ceba84fcfe19b1429a66f31d7","kind":"pyq"},{"id":"pyq-488","sourceNumber":488,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The information for the preparation of receipts and payments account is taken from","options":["Cash Book","Income and Expenditure Account","Cash Book and Balance Sheet","None"],"answer":0,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why A is correct — Cash Book:** The Receipts and Payments Account is a summary of cash and bank receipts and payments during the period, so it is prepared from the Cash Book and related cash records. It includes capital and revenue items and transactions relating to past/future periods. **Exam cue:** R&P Account = cash-book summary.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"8109f37b6955bf9ff52d42bd5e166a5308332cedf77835e77307063089c987fe","kind":"pyq"},{"id":"pyq-489","sourceNumber":489,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Money spent ₹10,000 as travelling expenses of the directors on trips abroad for purchase of capital assets is:","options":["Revenue expenditure","Capital expenditure","Deferred revenue expenditure","None"],"answer":1,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why B is correct — Capital expenditure:** Travel costs incurred by directors specifically to purchase capital assets are directly attributable to acquiring those assets when they are necessary for the acquisition. Such costs are capitalised as part of the asset cost rather than treated as routine revenue expenditure. **Exam cue:** expense directly linked to acquiring fixed asset → capitalise, subject to the applicable framework.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"734bb0a61c45dfdcad43bfa8d95389fc5c90fcfeea2aa904a4ee59306dbb3893","kind":"pyq"},{"id":"pyq-491","sourceNumber":491,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which one of the following is not prepared by non-profit organisations:","options":["Profit and Loss Account","Income & Expenditure Account","Receipts and Payments Account","Balance Sheet"],"answer":0,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why A is correct — Profit and Loss Account:** A not-for-profit organisation generally prepares a Receipts and Payments Account, an Income and Expenditure Account and a Balance Sheet. It does not normally prepare a commercial Profit and Loss Account; the Income and Expenditure Account serves the analogous purpose of showing current-period revenue income and expenses. **Exam cue:** NPO uses Income & Expenditure, not P&L.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"66304f66423b1ff3312df205c36a9340685840455deb6c01a2d96761faba1c35","kind":"pyq"},{"id":"pyq-492","sourceNumber":492,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The basic accounting equation is expressed as:","options":["Assets = Liabilities − Equity","Assets + Liabilities = Equity","Assets = Liabilities + Equity","Assets − Liabilities = Expenses"],"answer":2,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why C is correct:** The basic accounting equation is **Assets = Liabilities + Equity**. Assets are financed by claims from outsiders (liabilities) and owners (equity). Rearranged, Equity = Assets − Liabilities. **Memory cue:** what the business owns = what it owes + owners’ residual interest.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"5cfa68c5b1bfbc01368fce85c0341db42f842706a0e79aa23a0d6855a16ae0a0","kind":"pyq"},{"id":"pyq-493","sourceNumber":493,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Fixtures with a book value of ₹2,500 are sold for ₹1,600, and new fixtures of ₹4,000 are acquired. Cartage on purchase is ₹100. Which of the following statements is correct?","options":["Sale of old fixtures ₹1,600 → Capital Expenditure","Loss on sale of old fixtures ₹900 → Capital Expenditure","Purchase of new fixtures ₹4,000 + Cartage ₹100 → Capital Expenditure","Cartage on purchase ₹100 → Revenue Expenditure"],"answer":2,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why C is correct:** The cost of new fixtures is ₹4,000 and cartage on their purchase is ₹100. Cartage directly attributable to bringing the asset to its required location is capitalised, so total capital expenditure on the new fixtures is **₹4,100**. The old fixtures’ sale proceeds and loss on disposal are recorded separately; the loss is not capital expenditure on the new asset.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Fixtures with a book value of ₹2,500 are sold for ₹1,600, and new fixtures of ₹4,000 are acquired. Cartage on purchase is ₹100. Which of the following statements is correct?","options":["Sale of old fixtures ₹1,600 → Capital Expenditure","Loss on sale of old fixtures ₹900 → Capital Expenditure","Purchase of new fixtures ₹4,000 + Cartage ₹100 → Capital Expenditure","Cartage on purchase ₹100 → Revenue Expenditure"],"answer":2,"explanation":"**Why C is correct:** The cost of new fixtures is ₹4,000 and cartage on their purchase is ₹100. Cartage directly attributable to bringing the asset to its required location is capitalised, so total capital expenditure on the new fixtures is **₹4,100**. The old fixtures’ sale proceeds and loss on disposal are recorded separately; the loss is not capital expenditure on the new asset.","revision":"original","contentSignature":"0e7f84001a4c30b69e3d1d7e7fb830be0ec2e971cb6f6274769313965973c92c"}],"contentSignature":"0e7f84001a4c30b69e3d1d7e7fb830be0ec2e971cb6f6274769313965973c92c","legacySubject":"financial-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-494","sourceNumber":494,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Sundry Debtors = ₹50,000. Old Provision for Bad & Doubtful Debts = ₹4,000. New PBD required = 10% of will be:","options":["₹4,000","₹5,000","₹6,000","₹1,000"],"answer":3,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why D is correct — ₹1,000:** New provision required = 10% × Sundry Debtors ₹50,000 = ₹5,000. Existing provision = ₹4,000. Additional provision to be created = ₹5,000 − ₹4,000 = **₹1,000**, charged to the relevant expense account. **Exam cue:** provision adjustment = required closing provision − existing provision.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b1e7fbf3a77799c0db96d6784254c468432b3c78fd3f50c9b49219384881c086","kind":"pyq"},{"id":"pyq-495","sourceNumber":495,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In a Consignment, the relationship between the consignor and the consignee is that of:","options":["Master and Servant","Seller and Buyer","Principal and Agent","Partners"],"answer":2,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why C is correct — Principal and Agent:** In consignment, the consignor sends goods to the consignee to sell on the consignor’s behalf. Ownership generally remains with the consignor until sale to the customer; the consignee earns commission for acting as agent. **Exam cue:** consignment is agency, not a sale from consignor to consignee.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"f040a8ca17737a58347b3549c77fbf85ad9407de22a2410b1f886b4632585265","kind":"pyq"},{"id":"pyq-496","sourceNumber":496,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements about a Trial Balance is correct?","options":["It is an account showing only debit balances.","It proves complete accounting accuracy of the books of accounts.","It is a list of debit and credit balances extracted from ledger accounts to check arithmetical accuracy.","It forms a part of the final financial statements"],"answer":2,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why C is correct:** A trial balance lists debit and credit balances extracted from ledger accounts and checks their arithmetical agreement. It does not prove that every transaction is correct; errors such as complete omission, errors of principle and compensating errors may remain undetected. **Exam cue:** trial balance checks arithmetic, not complete accounting accuracy.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Which of the following statements about a Trial Balance is correct?","options":["It is an account showing only debit balances.","It proves complete accounting accuracy of the books of accounts.","It is a list of debit and credit balances extracted from ledger accounts to check arithmetical accuracy.","It forms a part of the final financial statements"],"answer":2,"explanation":"**Why C is correct:** A trial balance lists debit and credit balances extracted from ledger accounts and checks their arithmetical agreement. It does not prove that every transaction is correct; errors such as complete omission, errors of principle and compensating errors may remain undetected. **Exam cue:** trial balance checks arithmetic, not complete accounting accuracy.","revision":"original","contentSignature":"dc47b046bd46faead251afa8392e4be3a2039e38e15b5a187bd92daf6dcb933d"}],"contentSignature":"dc47b046bd46faead251afa8392e4be3a2039e38e15b5a187bd92daf6dcb933d","legacySubject":"financial-accounting","sourceBank":"shared","kind":"pyq"},{"id":"pyq-497","sourceNumber":497,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A machine is purchased for ₹1,20,000 with ₹20,000 installation expenses. Residual value is ₹30,000 and life is 10 years. What is the rate of depreciation under the Straight-Line","options":["8%","10%","12%","15%"],"answer":0,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why A is correct — 8%:** Total asset cost = ₹1,20,000 + installation ₹20,000 = ₹1,40,000. Depreciable amount = ₹1,40,000 − residual value ₹30,000 = ₹1,10,000. Annual straight-line depreciation = ₹1,10,000 ÷ 10 = ₹11,000. Rate on total cost = ₹11,000 ÷ ₹1,40,000 × 100 ≈ **7.86%, rounded to 8%**.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"4ae814173ccf54a2f13285362fb79c94987537230f59a64f11f4cdbdc8e06808","kind":"pyq"},{"id":"pyq-498","sourceNumber":498,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"An amount of ₹400 withdrawn by the owner for personal use was wrongly debited to Trade Expenses. The correct rectification entry is:","options":["Dr. Drawings A/c ₹400","Dr. Trade Expenses A/c ₹400","Dr. Capital A/c ₹200","Dr. Drawings A/c ₹200"],"answer":0,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why A is the intended rectification:** The owner’s personal withdrawal should be debited to Drawings, not Trade Expenses. Since Trade Expenses was wrongly debited by ₹400, the full correction requires crediting Trade Expenses ₹400 and debiting Drawings ₹400. Option A gives the correct debit side of the rectification, but the complete journal entry should include the credit to Trade Expenses. **Exam cue:** personal withdrawal → Drawings, not business expense.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"f27a449e43565f33895b0c73dac4ea6d899de1c3372a589fc7d46066f40703a6","kind":"pyq"},{"id":"pyq-501","sourceNumber":501,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Old furniture sold for ₹200 to Sethi was wrongly recorded in the Sales Book. Which of the following is the correct rectification entry?","options":["Dr. Sales A/c ₹200 Cr. Furniture A/c ₹200","Dr. Sethi A/c ₹200 Cr. Sales A/c ₹200","Dr. Furniture A/c ₹200 Cr. Sethi A/c ₹200","Dr. Cash A/c ₹200 Cr. Furniture A/c ₹200"],"answer":0,"source":"ICMAI CMA Foundation, Jun 2026","explanation":"**Why A is correct:** The sale of old furniture is a disposal of a fixed asset, not an ordinary sale of goods. If it was wrongly credited to Sales, debit Sales ₹200 to cancel the incorrect credit and credit Furniture ₹200 to remove the asset from the books for the recorded amount. The receipt from Sethi would remain recorded separately in the appropriate debtor/cash account. **Exam cue:** asset sale wrongly treated as goods sale → reverse Sales and credit the asset.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"f6ebbfc9f31196d7cac44965a60b5f4cf0ad6c9830571f10bc7d6c49513db9be","kind":"pyq"},{"id":"pyq-502","sourceNumber":502,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Given below are two statements : one is labelled as Assertion (A) and the other is labelled as Reason (R). Assertion (A) : Minority interestis that part of the net assets of a subsidiary attributable to interest which is held by outsiders. Reason (R) : Minority interest should be presented in the consolidated balance sheet as a part of equity of the parent’s shareholders. In the light of the above statements, choose the most appropriate answer from the options given below","options":["Both (A) and (R) are correct and (R) is the correct explanation of (A)","Both (A) and (R) are correct but (R) is not the correct explanation of (A)","(A) is correct but (R) is not correct","(A) is not correct but (R) is correct"],"answer":2,"source":"UGC NET Commerce, Dec 2025","explanation":"**Why C is correct — A true, R false:** Minority interest (now commonly called non-controlling interest) is the portion of a subsidiary’s net assets/equity attributable to shareholders other than the parent. It is presented separately within equity in consolidated financial statements, but it is **not** part of the parent shareholders’ own equity. **Exam cue:** NCI is equity of outside owners, shown separately from parent equity.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"2b69bf347226b21368667b9252b93a97b77da13903eb872c2d2373d1aade3d57","kind":"pyq"},{"id":"pyq-503","sourceNumber":503,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"What is the primary liability of the drawer of a bill of exchange or cheque?","options":["Liability to compensate the holder incase of dishonour.","Liability to pay the amount at maturity.","Liability to provide sufficient funds to the drawee.","Liability to pay the holder without any condition."],"answer":0,"source":"UGC NET Commerce, Jun 2025","explanation":"**Why A is correct:** The drawer’s liability on a bill of exchange or cheque is generally secondary: if the instrument is dishonoured and the holder gives proper notice where required, the drawer may be liable to compensate/pay the holder. The drawee is ordinarily the party directed to pay, and the drawer is not automatically the primary payer in every circumstance. **Exam cue:** drawer’s liability generally arises on dishonour, subject to legal conditions.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"bb1b57c19e012fb2f8a8ce78845185cad0a1298a84639a70c7c076cf5a881014","kind":"pyq"},{"id":"pyq-533","sourceNumber":533,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Acceptances, endorsements and other obligations are shown under head in the balance sheet.","options":["Other Assets","Other Liabilities","Contingent Liabilities","Borrowings"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct — Contingent Liabilities:** Acceptances, endorsements and other obligations that depend on future events or have not yet become recognised liabilities are disclosed under contingent liabilities in the traditional bank balance-sheet presentation. They are not ordinary borrowings or assets. **Exam cue:** contingent obligations → contingent liabilities/off-balance-sheet disclosures.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"323344345dac6c25922dc99572d548c5b80182b67536f5b2684018b4af4e82b3","kind":"pyq"},{"id":"pyq-534","sourceNumber":534,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In a small town, Shikha decides to open a bakery. She carefully separates her personal finances from the finances of the bakery. She opens a separate bank account for the bakery, maintains distinct accounting records, and ensures that all financial transactions related to the bakery are conducted through the business account. Shikha even goes the extra mile to obtain a unique business name and legal registration for her bakery. Which accounting concept is primarily applied in Shikha's approach to managing her bakery's finances?","options":["Money Measurement Concept","Business Entity Concept","Going Concern Concept","Dual Aspect Concept"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct — Business entity concept:** The business entity concept treats the bakery as separate from Shikha personally. Separate bank accounts and records ensure that the owner’s personal transactions are not mixed with business transactions. **Exam cue:** owner and business kept separate → business entity concept.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"ee157f0e4223c8445711050fcca092a14404d491c4f52889a5faa95c11a01f5c","kind":"pyq"},{"id":"pyq-535","sourceNumber":535,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"What is the correct journal entry in the drawer's books in the case of payment of a bill of exchange?","options":["Debit: Cash/Bank A/c. Credit: Bills Receivable A/c","Debit: Bills Payable A/c. Credit: Cash/Bank A/c.","Debit: Cash/Bank A/c. Credit: Bills Payable A/c","Debit: Bills Receivable A/c. Credit: Cash/Bank A/c."],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct:** In the drawer’s books, the bill is a receivable. When the drawee pays at maturity, the drawer receives cash/bank and the receivable is extinguished: **Bank/Cash Dr; Bills Receivable Cr**. The drawee’s books would instead debit Bills Payable and credit Bank/Cash. **Exam cue:** drawer receives; drawee pays.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"43103099e6111447b451559d9e02caafeb7b02d86250dfdbdc331115d7379b01","kind":"pyq"},{"id":"pyq-536","sourceNumber":536,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A reserve specifically represented by earmarked investments shall be termed as a:","options":["General Reserve","Capital Reserve","Fund","Surplus"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct — Fund:** A reserve specifically represented by earmarked investments is termed a fund. The reserve is the appropriation/retention of profits; the corresponding investment set aside to support it represents the fund. **Exam cue:** reserve backed by designated investments → fund.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"7fd13dd87cea4051f320da4190e62f368b48388eaf94e8292b23433654d1ffb7","kind":"pyq"},{"id":"pyq-537","sourceNumber":537,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following assets require a general provision of 15% on total outstanding?","options":["Standard Asset","Doubtful Asset","Sub-Standard Asset","Loss Asset"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is the supplied answer — Sub-standard asset:** The question reflects a specific bank-prudential provisioning table, in which a general provision rate is prescribed for sub-standard assets. Provisioning percentages can vary by type of exposure, security, agricultural/other loans and RBI directions, so the 15% figure should be treated as the source exam’s rule rather than a universal rate. **Banking note:** verify the applicable RBI master circular for current treatment.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"e84c1576648432d566596e5663ca74477c8cf505466b5a61bc5d4e23e913f59e","kind":"pyq"},{"id":"pyq-538","sourceNumber":538,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The balance of _____ A/c gets reflected in the credit side of the trial balance.","options":["drawings","purchases","suppliers","sales return"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct — Suppliers:** Suppliers/Creditors are personal liability accounts and normally carry credit balances because the business owes them money. Drawings, purchases and sales returns normally have debit balances under the conventional ledger treatment. **Exam cue:** amount owed to suppliers → credit balance.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"d7d78434d6192c1ee51bfc074bfe57769bfbf0edf25c561fa0cca4ca71308019","kind":"pyq"},{"id":"pyq-539","sourceNumber":539,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"When does a bill of exchange become a legal document?","options":["Upon acceptance by the drawee","Upon issuance by the drawer","Upon endorsement by the payee","Upon presentation to the bank"],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct — Acceptance by drawee:** Acceptance makes the drawee formally agree to pay the bill at maturity and creates the accepted bill obligation. A bill may be drawn/issued before acceptance, but acceptance is the key step that confirms the drawee’s liability on a time bill. **Exam cue:** drawee’s acceptance → formal commitment to pay.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"d200403078f93693916c017f6ed78d3244985fdf70662fc075019d413dbaf54f","kind":"pyq"},{"id":"pyq-540","sourceNumber":540,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following journal entries is passed in the books of drawee on discounting of bill with a bank by drawer?","options":["Debit: Bank A/c. Credit: Discount A/c","Debit: Discount A/c. Credit: Bank A/c","Debit: Discount A/c. Debit: Bank A/c. Credit: Bills Receivable A/c","No entry"],"answer":3,"source":"JAIIB AFM, 2023","explanation":"**Why D is correct — No entry in the drawee’s books:** When the drawer discounts a bill with a bank, the drawer transfers/discounts the bill and records the discount; the drawee has not yet made a payment or received funds. Therefore the drawee generally makes no entry merely because the drawer discounted the bill. The drawee records the liability and payment when relevant events occur. **Exam cue:** discounting by drawer alone → no entry for drawee.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"38e8cae0fdb2806943072945599b4a045b7fd08fa308ef21b1492e91aad71c04","kind":"pyq"},{"id":"pyq-541","sourceNumber":541,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is correct in the context of the Bank Reconciliation Statement? I. The Passbook is a mirror image of the cash book in the sense that credit entries in the cash book are reflected as debit entries in the passbook and debit entries in the cash book are reflected as credit entries in the passbook. II. Causes of difference between passbook and cashbook can be grouped under three headings. III. Amount Collected by Bank on Standing Instruction is an entry which does not require a change in the cashbook. IV. On dishonour of a cheque deposited by the trader, the bank will credit the customer's account.","options":["I and II only","II and IV only","I, II and IV only","I, II and III only"],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct — I and II only:** The Pass Book is the bank’s mirror image of the customer’s Cash Book: a cash-book debit generally appears as a bank credit and vice versa. Causes of BRS differences are commonly grouped into timing differences, errors and items entered by one party only. Amount collected by bank under standing instruction must be entered in the Cash Book, and a dishonoured cheque normally causes the bank to debit—not credit—the customer’s account. **Therefore III and IV are false.**","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"6e1fe70f9de11b7f8cec79eb9e9113bf2fef7904c7ebb86d82bb125d116d401d","kind":"pyq"},{"id":"pyq-542","sourceNumber":542,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following will not affect the trial balance? I. Compensating Errors II. Error of Commission III. Error of Complete Omission IV. Error of Principle","options":["III only","I and III only","I, II and III only","I, III and IV only"],"answer":3,"source":"JAIIB AFM, 2023","explanation":"**Why D is correct — I, III and IV:** Compensating errors can offset each other, complete omission leaves both sides unrecorded, and an error of principle may preserve debit-credit equality; these may not affect the trial balance. An error of commission can affect the trial balance if it creates an unequal amount or one-sided posting, but not every error of commission does. **Exam cue:** trial balance agreement does not prove the books are error-free.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"f7bc2847baa5f03b85a219f0e674313a14965e4b3333cf2b8abb24dfcf5e5e2e","kind":"pyq"},{"id":"pyq-544","sourceNumber":544,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"P accepts the bill drawn by Q for Rs. 5000. Which of the following is a correct journal entry passed in the books of P?","options":["Debit: Q's A/c. Credit: Cash/Bank A/c","Debit: Cash/ Bank A/c. Credit: Q's A/c","Debit: Q's A/c. Credit: Bills Payable A/c","Debit: Bills Payable A/c. Credit: Q's A/c"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct:** P is the drawee and accepts a bill drawn by Q. In P’s books, the acceptance creates a liability: debit Q’s account (or the appropriate payable/acceptance account) and credit Bills Payable. At maturity, P debits Bills Payable and credits Bank/Cash when paying. **Exam cue:** accept a bill as drawee → Bills Payable credit.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"ecb16c35f168ce2305a3579419ccf609ed58f335b002d677b3925ac28197224d","kind":"pyq"},{"id":"pyq-545","sourceNumber":545,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following journal entries is passed in the books of if a bill of exchange drawn by is honoured on maturity?","options":["Debit: Cash/Bank A/c. Credit: Bills Receivable A/c","Debit: Bills Receivable A/c. Credit: Cash/Bank A/c.","Debit: Cash/Bank A/c. Credit: Bills Payable A/c","Debit: Bills Payable A/c. Credit: Cash/Bank A/c."],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct:** In the drawer’s books, a bill receivable is an asset. When the drawee honours it at maturity, the drawer receives payment: debit Cash/Bank and credit Bills Receivable. In the drawee’s books, the opposite entry is passed to extinguish Bills Payable. **Exam cue:** honoured bill → drawer: Bank Dr / Bills Receivable Cr.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"fe57ab1618c702d0c8444c237970a694e749a17ddcf2cc12a705b5966cf05257","kind":"pyq"},{"id":"pyq-546","sourceNumber":546,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Choose the incorrect statement in the context of the bill of exchange. I. A bill of exchange can be drawn upon any person, including a bank. II. A bill of exchange does not require to be stamped. III. The acceptor of a bill of exchange is allowed two days of grace after the date of maturity of the bill.","options":["Only II","I and II only","II and III only","I, II and III"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct — II and III:** A bill of exchange must satisfy the applicable formal requirements, including stamping where required; the statement that it does not require stamping is incorrect. The statutory period of grace for a bill payable after date/sight is generally three days, not two, subject to the law’s applicability and exceptions. Statement I is generally true: a bill can be drawn on a person, including a bank. **Exam cue:** stamp requirement + three days of grace.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"c451599dcc75a5b1f59c32ddf756303d777007c009ba5b4d27c549be1e7e8342","kind":"pyq"},{"id":"pyq-547","sourceNumber":547,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A bill of exchange was created and issued by ' ' against 'A' for a payment of Rs. 20,000. What will be the journal entry in the books of ' if the bill is endorsed towards a third party, ' '?","options":["Debit: Z's A/c. Credit: X's A/c","Debit: Z's A/c. Credit: Bills Receivable A/c","Debit: A's A/c. Credit: Bills Receivable A/c","Debit: Z's A/c. Credit: Bills Payable A/c"],"answer":1,"source":"JAIIB AFM, 2023","explanation":"**Why B is correct:** When the drawer endorses a bill receivable to a third party Z, the drawer debits Z’s account because Z receives the right to collect the amount, and credits Bills Receivable to remove the instrument from the drawer’s books. The drawee’s Bills Payable liability remains until payment or other discharge. **Exam cue:** endorse bill → Endorsee Dr; Bills Receivable Cr.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"c3ea48b9a7445273ad3ceaebdfeb400c1218225462baeedf01b208642bd078a9","kind":"pyq"},{"id":"pyq-548","sourceNumber":548,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following statements is correct in the context of Accounting Standard - 18? I. This standard deals with the reporting of related party relationships and transactions between a reporting enterprise and its related parties. II. It states that the name of the related party and the nature of the related party relationship where control exists need not be disclosed if there are transactions between the related parties. III. The AS is applicable to general-purpose financial statements and consolidated financial statements.","options":["I only","III only","I and III only","I, II and III"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct — I and III only:** AS 18 deals with related-party relationships and transactions and applies to general-purpose financial statements and consolidated financial statements within its scope. When control exists, the name of the related party and nature of the relationship must be disclosed even if there are no transactions, so statement II is incorrect. **Exam cue:** disclose control relationship even without transactions.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"c01bc18c1b204ae628f030afa7fd68e81cd5ca375bb761b28a01aef7f4e48c6a","kind":"pyq"},{"id":"pyq-549","sourceNumber":549,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Goods amounting to Rs. 820 sold to XYZ were correctly entered in the sales book but posted to the account as Rs. 280. What will be the rectification entry?","options":["Debit: XYZ A/c (Rs. 540). Credit: Sales A/c (Rs. 540)","Debit: Sales A/c (Rs. 540). Credit: XYZ A/c (Rs. 540)","Debit: Suspense A/c (Rs. 540). Credit: XYZ A/c (Rs. 540)","Debit: XYZ A/c (Rs. 540). Credit: Suspense A/c (Rs. 540)"],"answer":3,"source":"JAIIB AFM, 2023","explanation":"**Why D is correct:** The Sales Book correctly records the sale of ₹820, but the customer’s account was debited only ₹280, leaving a short debit of ₹540. To correct the customer balance while using a suspense account for the one-sided difference, debit XYZ ₹540 and credit Suspense ₹540. **Calculation:** ₹820 − ₹280 = ₹540.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"f0f0fa0aaa1e9f84b42a4dab5c9291e99928e5c8d73d1895aeffd3515ec93408","kind":"pyq"},{"id":"pyq-550","sourceNumber":550,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In a lease transaction, the is eligible for depreciation on the asset and the entire lease rentals are taxed as income of the","options":["lessee, lessor","lessee, lessee","lessor, lessor","None of the above is correct"],"answer":2,"source":"JAIIB AFM, 2023","explanation":"**Why C is correct in the operating-lease framework:** In the traditional operating-lease treatment, the lessor owns the asset, claims depreciation and recognises lease rentals as income. The lessee recognises rental expense rather than depreciating the underlying asset. **Accounting-standard note:** under newer lease standards, lessee accounting has changed for many leases, so this is a source-era/lease-type-specific answer.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"e841034226eaf10b964a04e88330b83ee9819579922ebb265f154287622f5df0","kind":"pyq"},{"id":"pyq-551","sourceNumber":551,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"In the balance sheet of a bank, gold appears under the head and silver is shown under the head","options":["Investment, Other Assets","Other Assets, Investment","Investment, Investment","Other Assets, Other Assets"],"answer":0,"source":"JAIIB AFM, 2023","explanation":"**Why A is correct in the source’s bank balance-sheet format:** Gold held by a bank is shown under Investments, while silver is classified under Other Assets in the specific presentation used by this question. The classification depends on the prescribed bank balance-sheet schedule and the nature of the holding. **Exam cue:** use the schedule/classification specified by the source rather than assuming all precious metals are cash.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"00f83eb465d9ee06f82a085e6a85ba4d7ed087719b42e4753ebced14222feeb2","kind":"pyq"},{"id":"pyq-552","sourceNumber":552,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Where are the fictitious assets shown in the financial statements?","options":["Debit side of Profit and loss statement","Credit side of Profit and loss statement","Asset side of balance sheet","Liabilities side of balance sheet"],"answer":2,"source":"NABARD Grade A, 2020","explanation":"**Why C is the traditional answer — Asset side of the Balance Sheet:** Older accounting textbooks classified fictitious assets, such as preliminary expenses or accumulated losses, on the asset side even though they are not real resources. Modern financial reporting generally does not treat such items as genuine assets unless they meet asset-recognition criteria. **Exam note:** recognise this as traditional exam terminology.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"04d5ddf3e208eda2e2d6b927e5ef1c1c105056dca3b387acbd4cc38dc5c297c6","kind":"pyq"},{"id":"pyq-553","sourceNumber":553,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Accounting standards in India issued by:","options":["ICAI","INDIAN ACCOUNTING ASSOCIATION","IFCI","IIFCL"],"answer":0,"source":"NABARD Grade A, 2020","explanation":"**Why A is correct — ICAI:** The Institute of Chartered Accountants of India (ICAI) issues accounting standards through its standard-setting process and the relevant statutory approval/adoption framework. The Indian Accounting Association is a professional/academic body, not the primary statutory issuer of Indian Accounting Standards. **Exam cue:** Indian accounting standards → ICAI/central-government prescribed framework.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"1dca873105176e5037713271ba6b260e69b7e8c449ee341ec849ce205e15d9da","kind":"pyq"},{"id":"pyq-554","sourceNumber":554,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Financial position on particular date is shown in:","options":["Balance sheet","Trading account","Profit and loss account","Trial balance"],"answer":0,"source":"NABARD Grade A, 2020","explanation":"**Why A is correct — Balance Sheet:** A Balance Sheet shows assets, liabilities and equity at a particular date. Trading and Profit and Loss Accounts report performance over a period, while a trial balance is an internal listing of ledger balances. **Exam cue:** financial position “as at” a date → Balance Sheet.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"01d75f3f1f1e40515c6ed587ee8d708d7350ef9b00f9302ae9d1b7000faafeae","kind":"pyq"},{"id":"pyq-555","sourceNumber":555,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Under which method of depreciationthe value of a fixed asset is reduced uniformly over its useful life?","options":["Diminishing value method","Sum of years’ digit method","Straight line method","Horizontal line method"],"answer":2,"source":"NABARD Grade A, 2020","explanation":"**Why C is correct — Straight-line method:** Straight-line depreciation allocates the depreciable amount evenly over the asset’s useful life, producing the same depreciation charge each full year when estimates remain unchanged. Diminishing-balance methods produce larger charges earlier and smaller charges later. **Formula:** (cost − residual value)/useful life.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b55f689fb620088a9e87e3f05abcb2332509999f7ac283ed7ad082a292ee8997","kind":"pyq"},{"id":"pyq-556","sourceNumber":556,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Reserved stock is required to prevent","options":["Stock out","Stock loss","Loss by fire","To meet excess demand"],"answer":0,"source":"NABARD Grade A, 2020","explanation":"**Why A is correct — Stock-out:** Reserved/safety stock is held to protect against unexpected demand or delays in replenishment and reduce the risk of running out of inventory. It is not primarily designed to prevent fire or stock loss. **Exam cue:** safety stock → prevent stock-outs.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"2d42c24eb782f9e6d6843faa07c2ac4283847497761f4db319ba21b09a717295","kind":"pyq"},{"id":"pyq-557","sourceNumber":557,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"It is a special account that a firm prepares to show the distribution of profits/losses among the partners or shareholders. Name of such account is:","options":["Balance sheet","Trading account","Profit and loss account","P & L Appropriation account"],"answer":3,"source":"NABARD Grade A, 2020","explanation":"**Why D is correct — Profit and Loss Appropriation Account:** This account shows how earned profit or loss is allocated among partners/shareholders according to the relevant agreement and accounting rules. In a partnership, it may include partner salary, interest on capital and the division of residual profit. **Exam cue:** distribution of profit after calculation → appropriation account.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"6fe2f482b629554108fbe223d546568654e1052d283c13ea00f58c4f181e5ed3","kind":"pyq"},{"id":"pyq-558","sourceNumber":558,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Any decrease in the bank balance is recorded on ______ side of Cash Book and in _______ Column of Pass Book.","options":["Debit; Credit","Credit; Debit","Debit, Debit","Credit, Credit"],"answer":1,"source":"NABARD Grade A, 2020","explanation":"**Why B is correct — Credit in Cash Book; Debit in Pass Book:** A decrease in the customer’s bank balance is credited in the bank column of the Cash Book because the customer’s asset decreases. In the bank’s books, the customer’s deposit is a liability, so a decrease in that liability is recorded as a debit in the Pass Book. **Memory cue:** opposite entries in customer’s books and bank’s books.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"234efc687af10919e5f90aa27fa8341746a7348cfdb735041b2594faa791911e","kind":"pyq"},{"id":"pyq-559","sourceNumber":559,"subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Which of the following Liabilities are not shown in the Balance Sheet?","options":["Loans taken from the bank","Capital introduced by the promoter","Goods bought on credit from suppliers","Bank guarantee issued by a bank"],"answer":3,"source":"NABARD Grade A, 2020","explanation":"**Why D is correct — Bank guarantee issued by a bank:** A bank guarantee is generally a contingent/off-balance-sheet obligation until the relevant triggering event occurs, rather than an ordinary recognised liability in the customer’s balance sheet. Loans, owner’s capital and credit purchases are recognised liabilities/equity items. **Exam cue:** guarantee obligation → contingent liability disclosure, subject to applicable rules.","sourceVersion":"All-Exams Accounting PYQ Master v3 (12 Oct 2026)","explanationStatus":"expanded","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"fae852c5da32f75a6c686b9f7cf3d56c658ba7c69a9fab16b86c631968182d8f","kind":"pyq"},{"id":"original-extra-021","sourceNumber":"EX-021","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"The accounting equation is:","options":["Assets = Liabilities + Equity","Liabilities = Assets + Income","Equity = Assets + Liabilities","Assets = Income − Expenses"],"answer":0,"source":"Original practice question (not a previous-year question)","explanation":"The basic equation balances resources with claims by creditors and owners.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"342db0cbae727e54a72fe815ff2e924c2aac77b973ace3bc56cea1d63700dd21","kind":"mcq"},{"id":"original-extra-022","sourceNumber":"EX-022","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A trial balance primarily checks:","options":["Whether every transaction is genuine","Arithmetical agreement of ledger balances","Whether fraud is impossible","Market value of assets"],"answer":1,"source":"Original practice question (not a previous-year question)","explanation":"A trial balance checks debit-credit agreement but cannot detect every error.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"b5829c8c52cad5ee21eaef78b60a2b9bbd3bae799ff126afa2e173ac7fab154a","kind":"mcq"},{"id":"original-extra-023","sourceNumber":"EX-023","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Outstanding salary at year-end is:","options":["A prepaid asset of the business","A contingent asset of the business","An accrued expense and liability","A capital receipt of the year"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"Salary incurred but unpaid is accrued and recognised as an expense and liability.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Outstanding salary at year-end is:","options":["A prepaid asset","A contingent asset","An accrued expense and liability","A capital receipt"],"answer":2,"explanation":"Salary incurred but unpaid is accrued and recognised as an expense and liability.","revision":"original","contentSignature":"73e95a7c2513b7eda38a07fbe0059ef49b71d3a914398f7a3d20de4ce2036978"}],"contentSignature":"5bf974fb0dc9ee8e66a963500d85f7e90ec5921824500f705d639bc3e1b1dbf5","legacySubject":"financial-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-024","sourceNumber":"EX-024","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Depreciation is best described as:","options":["A valuation of the assets at their market price from time to time","An immediate cash payment made each year","A cash fund set aside every year","Systematic allocation of depreciable amount over useful life"],"answer":3,"source":"Original practice question (not a previous-year question)","explanation":"Depreciation allocates depreciable amount over useful life; it is not itself a cash reserve.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Depreciation is best described as:","options":["A valuation of assets at market price","An immediate cash payment","A cash fund set aside every year","Systematic allocation of depreciable amount over useful life"],"answer":3,"explanation":"Depreciation allocates depreciable amount over useful life; it is not itself a cash reserve.","revision":"original","contentSignature":"6fbb9ee50ec4d7971a8c983efc739280034ea58f43adf6e12b4b00c3fa28998e"}],"contentSignature":"0c908d069344865481c476372c44d67f3ce56afc47652ba4b690a2fe5ada9652","legacySubject":"financial-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-025","sourceNumber":"EX-025","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Under the straight-line method, annual depreciation is generally:","options":["Equal over each full year of useful life","Always nil in the last year of the useful life","Based only on the sales of each year","Higher in each successive year of use"],"answer":0,"source":"Original practice question (not a previous-year question)","explanation":"Straight-line depreciation allocates an equal amount per full year, subject to residual value and useful life.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"Under the straight-line method, annual depreciation is generally:","options":["Equal over each full year of useful life","Always zero in the last year","Based only on sales","Higher every year"],"answer":0,"explanation":"Straight-line depreciation allocates an equal amount per full year, subject to residual value and useful life.","revision":"original","contentSignature":"c8dfc3c817717fa9eff740c98bb0935461f6bf376343a3e71b93ad95a0aef32b"}],"contentSignature":"7fb176089ff10993a6439e8431192b1b85a9688e1621a12583f5c6bd0719dc27","legacySubject":"financial-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-026","sourceNumber":"EX-026","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A bank reconciliation statement explains differences between:","options":["The sales and the purchases of the period","Cash book bank balance and bank statement balance","The assets and the capital of the business","The trial balance and the profit of the year under audit"],"answer":1,"source":"Original practice question (not a previous-year question)","explanation":"Timing differences and errors can cause the two bank balances to differ.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A bank reconciliation statement explains differences between:","options":["Sales and purchases","Cash book bank balance and bank statement balance","Assets and capital","Trial balance and profit only"],"answer":1,"explanation":"Timing differences and errors can cause the two bank balances to differ.","revision":"original","contentSignature":"f45b15fbf907aab51811a1b3126978ff32b4e917ad1e3ef534a3255cdcac8d4c"}],"contentSignature":"b0c7b1de42fe6f8fa95ad1fc27fab1396aabbc5df71aedd0d8bacd8cb6524458","legacySubject":"financial-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-027","sourceNumber":"EX-027","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A provision is generally recognised when there is a present obligation, probable outflow and:","options":["Guaranteed profit","Only a future intention","Reliable estimate of amount","No past event"],"answer":2,"source":"Original practice question (not a previous-year question)","explanation":"These are the core recognition conditions for a provision under common accounting frameworks.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"37d5df8d8d8f65d8a0f9052e48e7a3cd5d6a8adb118a1db72c86d92d25b99eb2","kind":"mcq"},{"id":"original-extra-028","sourceNumber":"EX-028","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"Inventory is commonly measured at:","options":["Replacement cost in all cases","Selling price less profit only","Higher of cost and selling price","Lower of cost and net realisable value"],"answer":3,"source":"Original practice question (not a previous-year question)","explanation":"Inventory is generally measured at the lower of cost and net realisable value.","legacySubject":"financial-accounting","sourceBank":"shared","contentSignature":"1e7d3411746616f228347e1ebb9fc62d7048d4b9e78f3ba586c39124ca6a0e69","kind":"mcq"},{"id":"original-extra-029","sourceNumber":"EX-029","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A suspense account may be used temporarily when:","options":["Trial balance disagrees and the difference is not yet located","Cash has actually been stolen from the business","Every entry in the books is already correct","A profit has definitely been earned in the year"],"answer":0,"source":"Original practice question (not a previous-year question)","explanation":"A suspense account temporarily holds an unexplained difference pending investigation.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A suspense account may be used temporarily when:","options":["Trial balance disagrees and the difference is not yet located","Cash is always missing","All entries are correct","Profit is definitely earned"],"answer":0,"explanation":"A suspense account temporarily holds an unexplained difference pending investigation.","revision":"original","contentSignature":"1bdd19970ec6dba78b1820dbf93855cb7f3de1e5c9a38ada17c5d7df09d51266"}],"contentSignature":"ca944f6e33581110f3f2eb2c05fe5d195fe052fd247bbf117a79829e360c2a4a","legacySubject":"financial-accounting","sourceBank":"shared","kind":"mcq"},{"id":"original-extra-030","sourceNumber":"EX-030","subject":"financial-accounting","subjectName":"Advanced Financial Accounting","question":"A credit purchase of goods is recorded by debiting:","options":["Trade Payables for the amount of the invoice","Purchases/Inventory as applicable","The Sales Account for the amount","The Capital Account of the proprietor"],"answer":1,"source":"Original practice question (not a previous-year question)","explanation":"The purchase account or inventory is debited and the supplier payable is credited.","revision":"R2","revisionChanged":true,"revisionHistory":[{"question":"A credit purchase of goods is recorded by debiting:","options":["Trade Payables","Purchases/Inventory as applicable","Sales","Capital"],"answer":1,"explanation":"The purchase account or inventory is debited and the supplier payable is credited.","revision":"original","contentSignature":"0cd4fd432888a7c634665e4fa29955ae6a4be2786ae298eb1808fe6e9d674584"}],"contentSignature":"490b6292003a720aa282ce6e3a3b0c8c6b4eca4f4dfc12c84a3659e53613da18","legacySubject":"financial-accounting","sourceBank":"shared","kind":"mcq"}]};
